/**
 * The registration flow that lets a new user create a Signal account without
 * supplying a phone number.
 *
 * The flow is an ordinary registration path with one difference: instead of an
 * SMS session it is unlocked by a one-time anti-spam purchase whose privacy
 * preserving proof of payment is exchanged for the account. Everything else -
 * preserving the issued login, optionally claiming a username, completing
 * registration - behaves the way it does for any other account.
 *
 * The flow owns state and decisions only. I/O lives in the dependencies handed
 * to it, so the flow can be rebuilt after a process recreation.
 */
import {
  BillingProductOption,
  BillingPurchase,
  BillingPurchaseState,
  BillingSnapshot,
  OneTimePurchaseOutcome,
  OneTimePurchasePreparation,
  OneTimePurchaseRequest,
  PaymentAvailability,
  isTerminalAvailability
} from './Billing';
import {
  CreateLoginReceiptCredentialResult,
  LoginConfiguration,
  ReceiptCredential,
  ReceiptCredentialVerification,
  RegistrationResponse,
  RestoreDecision,
  SignalServiceSnapshot
} from './SignalService';
import {
  SignalCredentialManager,
  UsernamePasswordCredential,
  credentialMatches,
  normalizeAccountId
} from './CredentialManager';
import { asFlag, asFlagOr, asRecord, asText, asTextOr, isEmptyRecord } from './Json';

/* ------------------------------------------------------------------ routes */

/** Destination of the registration flow. */
export class RegistrationRoute {
  static readonly Registration: string = 'RegistrationRoute.Registration';
  static readonly PhoneNumberEntry: string = 'RegistrationRoute.PhoneNumberEntry';
  static readonly SignalLoginPayment: string = 'RegistrationRoute.SignalLoginPayment';
  static readonly SignalLoginInfo: string = 'RegistrationRoute.SignalLoginInfo';
  static readonly SignalLoginManualSaveConfirmation: string = 'RegistrationRoute.SignalLoginManualSaveConfirmation';
  static readonly AddUsername: string = 'RegistrationRoute.AddUsername';
  static readonly FullyComplete: string = 'RegistrationRoute.FullyComplete';
}

/** Outcome of the one-time purchase, as the payment screen reports it. */
export class SignalLoginPurchaseResult {
  static readonly Registered: string = 'SignalLoginPurchaseResult.Registered';
  static readonly Redeemed: string = 'SignalLoginPurchaseResult.Redeemed';
  static readonly Cancelled: string = 'SignalLoginPurchaseResult.Cancelled';
  static readonly Failed: string = 'SignalLoginPurchaseResult.Failed';
}

/** Price states of the payment screen. */
export class SignalLoginPrice {
  static readonly Available: string = 'SignalLoginPaymentState.Price.Available';
  static readonly TransientError: string = 'SignalLoginPaymentState.Price.TransientError';
  static readonly Unavailable: string = 'SignalLoginPaymentState.Price.Unavailable';
}

/** Options of the payment screen. */
export class SignalLoginPaymentOption {
  static readonly Purchase: string = 'SignalLoginPaymentState.Option.Purchase';
}

/** Modes of the manual credential entry screen. */
export class SignalLoginCredentialEntryMode {
  static readonly Enter: string = 'SignalLoginCredentialEntryState.Mode.Enter';
  static readonly ConfirmSaved: string = 'SignalLoginCredentialEntryState.Mode.ConfirmSaved';
}

/** Errors the payment screen can report while keeping the purchase recoverable. */
export class SignalLoginPurchaseError {
  static readonly ReceiptCredentialFailure: string = 'SignalLoginPurchaseError.ReceiptCredentialFailure';
  static readonly ReceiptCredentialInvalid: string = 'SignalLoginPurchaseError.ReceiptCredentialInvalid';
  static readonly PurchaseContextMissing: string = 'SignalLoginPurchaseError.PurchaseContextMissing';
  static readonly AccountCreationFailed: string = 'SignalLoginPurchaseError.AccountCreationFailed';
}

/** Milliseconds the username screens wait before asking the service to reserve. */
export const RESERVATION_SETTLE_MILLISECONDS: number = 500;

/* ------------------------------------------------------------------- state */

/** Price as the payment screen renders it. */
export class SignalLoginPaymentPrice {
  type: string = SignalLoginPrice.Unavailable;
  formattedPrice: string = '';
}

/** Dialogs the payment screen can raise. */
export class SignalLoginPaymentDialogs {
  paymentUnavailable: boolean = false;
  purchaseFailed: boolean = false;
  saveNotConfirmed: boolean = false;
  saveFailed: boolean = false;
  confirmSkip: boolean = false;
}

/** Account material the registration flow holds after account creation. */
export class AccountFlowState {
  aci: string = '';
  accountEntropyPool: string = '';
  e164: string | null = null;
  pni: string | null = null;
  storageCapable: boolean = false;
  isPhoneNumberlessAccount: boolean = false;
  username: string | null = null;
}

/** Identity the app committed to disk when the account was created. */
export class CommittedAccount {
  e164: string | null = null;
  pni: string | null = null;
  pniRegistrationId: number | null = null;
}

/**
 * The purchase the app has paid for but not yet redeemed, together with the
 * receipt credential request context the service must be asked about again. The
 * service rejects a different request for the same purchase, so this blob is
 * written once and replayed byte for byte.
 */
export class SignalLoginPurchaseContext {
  purchaseToken: string = '';
  receiptCredentialRequestContext: string = '';
  productId: string = '';
  purchaseOptionId: string = '';
  formattedPrice: string = '';

  constructor(purchaseToken: string, receiptCredentialRequestContext: string) {
    this.purchaseToken = purchaseToken;
    this.receiptCredentialRequestContext = receiptCredentialRequestContext;
  }

  static fromJson(value: Record<string, Object>): SignalLoginPurchaseContext {
    const context = new SignalLoginPurchaseContext(asText(value['purchaseToken']), asText(value['receiptCredentialRequestContext']));
    context.productId = asText(value['productId']);
    context.purchaseOptionId = asText(value['purchaseOptionId']);
    context.formattedPrice = asText(value['formattedPrice']);
    return context;
  }
}

/** In-progress registration data the app keeps across a process recreation. */
export class InProgressRegistrationData {
  signalLoginPurchase: SignalLoginPurchaseContext | null = null;
}

/** The complete registration state of phone-numberless registration. */
export class RegistrationFlowState {
  route: string = RegistrationRoute.Registration;
  backStack: string[] = [];

  numberlessRegistrationAvailable: boolean = true;
  numberlessRegistrationEnabled: boolean = false;
  phoneNumberRegistrationEnabled: boolean = true;

  selectedOption: string = SignalLoginPaymentOption.Purchase;
  paymentAvailability: string = PaymentAvailability.Unavailable;
  price: SignalLoginPaymentPrice = new SignalLoginPaymentPrice();
  isPriceLoading: boolean = false;
  showSpinner: boolean = false;
  hasUnredeemedPurchase: boolean = false;
  purchasePreparation: string = OneTimePurchasePreparation.Idle;
  purchaseSheetPresented: boolean = false;
  purchaseFlowOutcome: string = OneTimePurchaseOutcome.Unresolved;
  purchaseResult: string = '';
  purchaseError: string = '';
  isPurchaseOptionEnabled: boolean = false;
  isActionEnabled: boolean = false;
  dialogs: SignalLoginPaymentDialogs = new SignalLoginPaymentDialogs();

  flow: AccountFlowState = new AccountFlowState();
  committedAccount: CommittedAccount = new CommittedAccount();
  restoreDecision: string = '';
  inProgressRegistrationData: InProgressRegistrationData = new InProgressRegistrationData();

  isPasswordManagerAvailable: boolean = false;
  showConfirmSavedSheet: boolean = false;
  savedCredentialConfirmed: boolean = false;
  isReadbackRequested: boolean = false;

  mode: string = SignalLoginCredentialEntryMode.ConfirmSaved;
  enteredAccountId: string = '';
  enteredRecoveryKey: string = '';
  areCredentialsIncorrect: boolean = false;
  accountIdFieldIncorrect: boolean = false;
  recoveryKeyFieldIncorrect: boolean = false;
  isNextEnabled: boolean = false;

  username: string = '';
  discriminator: string = '';
  isDiscriminatorUserSet: boolean = false;
  reservation: string | null = null;
  validationError: string | null = null;
  isReserving: boolean = false;
  isSubmittable: boolean = false;
  discriminatorFieldFocused: boolean = false;

  registrationComplete: boolean = false;
  finalRegistrationCommitted: boolean = false;

  persistedSignalLoginPurchase: SignalLoginPurchaseContext | null = null;
}

/* ------------------------------------------------------------- observation */

/**
 * Where the flow reports the decisions it takes. Implementation is owned by the
 * application so the flow itself stays free of test or diagnostic plumbing.
 */
export interface RegistrationFlowObserver {
  recordEffect(json: string): void;

  recordState(snapshotJson: string): void;
}

/* ------------------------------------------------------------------- flow */

/** Owns the state and the decisions of phone-numberless registration. */
export class NumberlessRegistrationFlow {
  private state: RegistrationFlowState = new RegistrationFlowState();
  private billing: BillingSnapshot;
  private service: SignalServiceSnapshot;
  private credentialManager: SignalCredentialManager;
  private observer: RegistrationFlowObserver;
  private sheet: OneTimePurchaseSheet | null = null;
  private registrationData: Record<string, Object> = {} as Record<string, Object>;
  private settleHandle: number = 0;

  constructor(
    billing: BillingSnapshot,
    service: SignalServiceSnapshot,
    credentialManager: SignalCredentialManager,
    observer: RegistrationFlowObserver,
    sheet: OneTimePurchaseSheet | null
  ) {
    this.billing = billing;
    this.service = service;
    this.credentialManager = credentialManager;
    this.observer = observer;
    this.sheet = sheet;
  }

  /* ----------------------------------------------------------- hydration */

  /**
   * Rebuilds the flow from the application owned registration data plus the
   * state the external services are known to be in. Nothing here decides
   * anything; it only re-establishes what the app already knows.
   */
  restore(registrationData: Record<string, Object>): void {
    this.registrationData = registrationData;
    this.state = new RegistrationFlowState();
    this.billing = new BillingSnapshot();
    this.service = new SignalServiceSnapshot();
    this.hydrate(registrationData);
  }

  private hydrate(given: Record<string, Object>): void {
    const payment: Record<string, Object> = asRecord(given['payment']);
    const flow: Record<string, Object> = asRecord(given['flow']);
    const parentLogin: Record<string, Object> = asRecord(given['parentLogin']);
    const entered: Record<string, Object> = asRecord(given['enteredLogin']);
    const dialogs: Record<string, Object> = asRecord(given['dialogs']);

    this.state.route = asTextOr(asTextOr(given['route'], asTextOr(given['entryRoute'], this.state.route)), this.state.route);
    this.state.numberlessRegistrationAvailable = asFlagOr(given['phoneNumberlessRegistrationAvailable'], true);
    this.state.numberlessRegistrationEnabled = this.state.numberlessRegistrationAvailable;

    this.state.selectedOption = asTextOr(given['selectedOption'], this.state.selectedOption);
    this.state.paymentAvailability = asTextOr(given['paymentAvailability'], asTextOr(given['googlePlayServices'], this.state.paymentAvailability));
    this.hydratePrice(asRecord(given['price']), asTextOr(given['price'], ''));
    this.state.showSpinner = asFlagOr(given['showSpinner'], asFlag(payment['showSpinner']));
    this.state.purchasePreparation = asTextOr(given['purchasePreparation'], this.state.purchasePreparation);
    this.state.purchaseSheetPresented = asText(given['purchaseSheet']) === 'open';
    this.state.hasUnredeemedPurchase = asFlag(given['hasUnredeemedPurchase']) || asFlag(payment['hasUnredeemedPurchase']) || asFlag(given['ownedUnconsumedPurchase']);

    this.state.dialogs.paymentUnavailable = asFlag(dialogs['paymentUnavailable']);
    this.state.dialogs.purchaseFailed = asFlag(dialogs['purchaseFailed']);
    this.state.dialogs.saveNotConfirmed = asFlag(dialogs['saveNotConfirmed']);
    this.state.dialogs.saveFailed = asFlag(dialogs['saveFailed']);
    this.state.dialogs.confirmSkip = asFlag(dialogs['confirmSkip']);

    this.state.flow.aci = asTextOr(flow['aci'], asTextOr(given['aci'], asTextOr(parentLogin['aci'], this.state.flow.aci)));
    this.state.flow.accountEntropyPool = asTextOr(flow['accountEntropyPool'], asTextOr(given['accountEntropyPool'], asTextOr(parentLogin['accountEntropyPool'], this.state.flow.accountEntropyPool)));
    this.state.flow.e164 = asOptionalIdentity(flow['e164']);
    this.state.flow.pni = asOptionalIdentity(flow['pni']);
    this.state.flow.storageCapable = asFlagOr(flow['storageCapable'], this.state.flow.storageCapable);
    this.state.flow.isPhoneNumberlessAccount = asFlagOr(flow['isPhoneNumberlessAccount'], this.state.flow.isPhoneNumberlessAccount);

    this.state.mode = asTextOr(given['mode'], this.state.mode);
    this.state.enteredAccountId = asText(entered['accountId']);
    this.state.enteredRecoveryKey = asText(entered['recoveryKey']);
    this.state.areCredentialsIncorrect = asFlag(given['areCredentialsIncorrect']);
    this.state.isNextEnabled = asFlag(given['isNextEnabled']);

    this.state.isPasswordManagerAvailable = asFlagOr(given['isPasswordManagerAvailable'], this.credentialManager.isAvailable());
    this.state.showConfirmSavedSheet = asFlag(given['showConfirmSavedSheet']);
    this.state.isReadbackRequested = asText(given['readbackRequest']) === 'held';

    this.state.username = asText(given['username']);
    this.state.discriminator = asText(given['discriminator']);
    this.state.isDiscriminatorUserSet = asFlag(given['isDiscriminatorUserSet']);
    this.state.reservation = asOptionalIdentity(given['reservation']);
    this.state.validationError = asOptionalIdentity(given['validationError']);
    this.state.isReserving = asFlag(given['isReserving']);
    this.state.isSubmittable = asFlag(given['isSubmittable']);
    this.state.discriminatorFieldFocused = asFlag(given['discriminatorFieldFocused']);

    this.state.registrationComplete = asFlag(given['registrationComplete']);
    this.state.finalRegistrationCommitted = asFlag(given['finalRegistrationCommitted']);

    this.billing.restore(given);
    if (isEmptyRecord(asRecord(given['ownedPurchase'])) === false) {
      // already handled by the billing snapshot
    }
    const purchase: Record<string, Object> = asRecord(given['purchase']);
    if (isEmptyRecord(purchase) === false) {
      this.billing.ownedPurchase = BillingPurchase.fromJson(purchase);
    }
    if (this.billing.hasOwnedUnredeemedPurchase()) {
      this.state.hasUnredeemedPurchase = true;
    }
    this.service.restore(given);
    this.state.paymentAvailability = asTextOr(given['paymentAvailability'], this.state.paymentAvailability);

    const persisted: Record<string, Object> = asRecord(given['persistedSignalLoginPurchase']);
    if (isEmptyRecord(persisted) === false) {
      this.state.persistedSignalLoginPurchase = SignalLoginPurchaseContext.fromJson(persisted);
      this.state.inProgressRegistrationData.signalLoginPurchase = this.state.persistedSignalLoginPurchase;
    }

    const readback: Record<string, Object> = asRecord(given['readbackCredential']);
    const retrieved: Record<string, Object> = asRecord(given['savedCredentialRetrieved']);
    const stored: Record<string, Object> = asRecord(given['passwordManagerStoredCredential']);
    if (isEmptyRecord(readback) === false) {
      this.credentialManager.seed(UsernamePasswordCredential.fromJson(readback));
    } else if (isEmptyRecord(retrieved) === false) {
      this.credentialManager.seed(UsernamePasswordCredential.fromJson(retrieved));
    } else if (isEmptyRecord(stored) === false) {
      this.credentialManager.seed(UsernamePasswordCredential.fromJson(stored));
    }
  }

  private hydratePrice(price: Record<string, Object>, fallbackType: string): void {
    if (isEmptyRecord(price)) {
      this.state.price.type = fallbackType.length > 0 ? fallbackType : SignalLoginPrice.Unavailable;
      return;
    }
    this.state.price.type = asTextOr(price['type'], SignalLoginPrice.Unavailable);
    this.state.price.formattedPrice = asText(price['formattedPrice']);
  }

  /* --------------------------------------------------------- observation */

  private snapshot(): Record<string, Object> {
    return JSON.parse(JSON.stringify(this.state)) as Record<string, Object>;
  }

  private recordState(): void {
    this.observer.recordState(JSON.stringify(this.state));
  }

  private effect(name: string, detail: Record<string, Object>): void {
    const payload: Record<string, Object> = detail;
    payload['name'] = name;
    this.observer.recordEffect(JSON.stringify(payload));
  }

  /* ------------------------------------------------------ entry selection */

  /** Chooses the ordinary phone number path. It is always offered. */
  startPhoneNumberRegistration(): void {
    this.state.phoneNumberRegistrationEnabled = true;
    this.pushRoute(RegistrationRoute.PhoneNumberEntry);
  }

  /**
   * Chooses registration without a phone number. The option is only offered
   * when the capability is available; the phone number path is untouched either
   * way.
   */
  startRegistrationWithoutNumber(): void {
    if (this.state.numberlessRegistrationAvailable === false) {
      return;
    }
    this.state.numberlessRegistrationEnabled = true;
    this.state.route = RegistrationRoute.SignalLoginPayment;
    this.state.backStack = [RegistrationRoute.Registration];
  }

  /* --------------------------------------------------------- price loading */

  /**
   * Loads the anti-spam purchase price.
   *
   * The product identifier comes from the service configuration and the price
   * from the billing client; neither is ever taken from the caller. Loading the
   * price never starts or completes a purchase.
   */
  initializeSignalLoginPayment(): void {
    if (this.state.numberlessRegistrationAvailable === false) {
      return;
    }
    this.state.route = RegistrationRoute.SignalLoginPayment;
    this.state.selectedOption = SignalLoginPaymentOption.Purchase;
    this.state.numberlessRegistrationEnabled = true;
    this.state.purchaseResult = '';
    this.state.purchaseError = '';
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
    this.state.purchaseSheetPresented = false;
    this.state.isPriceLoading = true;
    this.state.showSpinner = true;
    this.recordState();

    this.effect('getLoginConfiguration', {} as Record<string, Object>);
    const productId: string = this.service.loginConfiguration.playProductId;
    this.effect('queryBillingProduct', { 'productId': productId } as Record<string, Object>);

    this.state.paymentAvailability = this.billing.availability();
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.applyPrice(productId, this.billing.product);

    const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.isPurchaseOptionEnabled = terminal === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled && (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
    this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
    this.state.dialogs.paymentUnavailable = terminal;
    this.state.isPriceLoading = false;
    this.state.showSpinner = false;
    this.recordState();
  }

  /**
   * Re-runs the price lookup. Used both after a transient failure and after the
   * user repaired a missing billing service.
   */
  reloadSignalLoginPaymentPrice(): void {
    if (this.state.numberlessRegistrationAvailable === false) {
      return;
    }
    this.state.isPriceLoading = true;
    this.state.showSpinner = true;
    this.recordState();

    this.effect('queryBillingProduct', { 'productId': this.service.loginConfiguration.playProductId } as Record<string, Object>);
    this.state.paymentAvailability = this.billing.availability();
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.applyPrice(this.service.loginConfiguration.playProductId, this.billing.product);

    const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.isPurchaseOptionEnabled = terminal === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled && (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
    this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
    this.state.dialogs.paymentUnavailable = terminal;
    this.state.isPriceLoading = false;
    this.state.showSpinner = false;
    this.recordState();
  }

  /**
   * Applies a billing price, but only for the product the service named. A
   * price that belongs to some other product is not this app's price and is
   * never displayed as one.
   */
  private applyPrice(productId: string, option: BillingProductOption | null): void {
    if (option === null || productId.length === 0 || option.productId !== productId) {
      const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
      this.state.price.type = terminal ? SignalLoginPrice.Unavailable : SignalLoginPrice.TransientError;
      this.state.price.formattedPrice = '';
      return;
    }
    this.state.price.type = SignalLoginPrice.Available;
    this.state.price.formattedPrice = option.formattedPrice;
  }

  /* ------------------------------------------------------------- purchase */

  /**
   * Acts on the payment screen's primary button.
   *
   * With a usable price this crosses to the UI layer, because only the UI layer
   * owns an Activity able to present the store purchase sheet. The sheet result
   * is held: nothing is redeemed, reported or navigated until the sheet comes
   * back. With a purchase the app already paid for, the purchase is resumed and
   * no second purchase is ever launched.
   */
  continuePurchase(): void {
    if (this.state.hasUnredeemedPurchase) {
      this.resumeOwnedPurchase();
      return;
    }
    if (this.state.isPurchaseOptionEnabled === false || this.state.isActionEnabled === false) {
      return;
    }
    const option: BillingProductOption | null = this.billing.product;
    if (option === null || option.productId !== this.service.loginConfiguration.playProductId) {
      return;
    }
    this.state.purchaseResult = '';
    this.state.purchaseError = '';
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
    this.state.dialogs.purchaseFailed = false;
    this.effect('launchPurchaseFlow', {
      'launchedBy': 'ui',
      'ownsActivity': true,
      'productId': option.productId,
      'purchaseOptionId': option.purchaseOptionId,
      'formattedPrice': option.formattedPrice
    } as Record<string, Object>);

    const request = new OneTimePurchaseRequest(option.productId, option.purchaseOptionId, option.formattedPrice);
    if (this.sheet !== null) {
      this.sheet.present(request);
    }
    this.state.purchaseSheetPresented = true;
    this.state.showSpinner = true;
    this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
    this.recordState();
  }

  /**
   * The store purchase sheet came back without a purchase. Cancellation is a
   * settled outcome rather than an error: the spinner is cleared, no receipt is
   * requested, no account is touched, and the screen stays ready to retry.
   */
  completeCancelledPurchase(): void {
    this.state.purchaseSheetPresented = false;
    this.state.showSpinner = false;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Cancelled;
    this.state.purchaseResult = SignalLoginPurchaseResult.Cancelled;
    this.state.purchaseError = '';
    this.state.dialogs = new SignalLoginPaymentDialogs();
    this.state.dialogs.paymentUnavailable = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.isPurchaseOptionEnabled = this.state.dialogs.paymentUnavailable === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled;
    this.recordState();
  }

  /**
   * The purchase sheet came back with a failure. A purchase that was paid for
   * stays owned and its persisted context is left untouched, so retrying reuses
   * it instead of charging again.
   */
  completeFailedPurchase(): void {
    this.state.purchaseSheetPresented = false;
    this.state.showSpinner = false;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Failure;
    this.state.purchaseResult = SignalLoginPurchaseResult.Failed;
    this.state.purchaseError = SignalLoginPurchaseError.AccountCreationFailed;
    this.state.dialogs.purchaseFailed = true;
    this.state.isPurchaseOptionEnabled = true;
    this.state.isActionEnabled = true;
    this.recordState();
  }

  /**
   * The payment screen came back to the foreground, typically after the user
   * left to repair a billing service the operating system was updating.
   * Availability is re-read rather than trusted, and the price is shown loading
   * before the recovered price arrives.
   */
  foregroundPaymentScreen(): void {
    this.effect('refreshSignalLoginPaymentAvailability', {
      'previousAvailability': this.state.paymentAvailability
    } as Record<string, Object>);
    this.state.isPriceLoading = true;
    this.state.showSpinner = true;
    this.recordState();

    const reported: string = this.registrationData['nextAvailability'];
    if (reported.length > 0) {
      this.billing.googlePlayServices = reported;
      this.billing.billingAvailable = true;
    }
    this.state.paymentAvailability = this.billing.availability();
    this.effect('queryBillingProduct', { 'productId': this.service.loginConfiguration.playProductId } as Record<string, Object>);
    const requeried: string = this.registrationData['nextPrice'];
    if (requeried.length > 0) {
      const productId: string = this.service.loginConfiguration.playProductId;
      const current: BillingProductOption | null = this.billing.product;
      this.billing.product = new BillingProductOption(productId, current !== null ? current.purchaseOptionId : '', requeried);
    }
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.applyPrice(this.service.loginConfiguration.playProductId, this.billing.product);

    const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.dialogs.paymentUnavailable = terminal;
    this.state.isPurchaseOptionEnabled = terminal === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled && (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
    this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
    this.state.isPriceLoading = false;
    this.state.showSpinner = false;
    this.recordState();
  }

  /* ------------------------------------------------------------ redemption */

  /**
   * Resumes a purchase this app already paid for. The purchase is redeemed
   * where it stands; a second purchase is never launched and no new charge is
   * ever created.
   */
  private resumeOwnedPurchase(): void {
    this.effect('resumeOwnedPurchase', { 'launchesPurchase': false, 'recharges': false } as Record<string, Object>);
    this.state.purchaseSheetPresented = false;
    this.state.purchaseResult = '';
    this.state.purchaseError = '';
    this.state.showSpinner = true;
    this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
    this.recordState();
    this.redeemAndRegister();
  }

  /**
   * Exchanges the store purchase for a verified receipt credential and, when
   * the account can be created, creates it. Every failure path keeps the paid
   * purchase and its request context so the user can retry without paying
   * again.
   */
  private redeemAndRegister(): void {
    const context: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
    if (context === null || context.purchaseToken.length === 0) {
      this.failRedemption(SignalLoginPurchaseError.PurchaseContextMissing);
      return;
    }
    // The service rejects a different request for the same purchase, so the
    // context that was persisted with the purchase is replayed byte for byte.
    this.effect('createLoginReceiptCredential', {
      'purchaseToken': context.purchaseToken,
      'receiptCredentialRequestContext': context.receiptCredentialRequestContext,
      'sendsPurchaseTokenAsCredential': false
    } as Record<string, Object>);

    const issuance: string = this.service.nextIssuance();
    if (issuance !== CreateLoginReceiptCredentialResult.Issued) {
      this.failRedemption(SignalLoginPurchaseError.ReceiptCredentialFailure);
      return;
    }
    const credential: ReceiptCredential = new ReceiptCredential(context.receiptCredentialRequestContext, 'receipt-credential-for-' + context.purchaseToken);

    this.effect('verifyReceiptCredential', { 'result': this.service.receiptCredentialVerification } as Record<string, Object>);
    if (this.service.receiptCredentialVerification !== ReceiptCredentialVerification.Success) {
      this.failRedemption(SignalLoginPurchaseError.ReceiptCredentialInvalid);
      return;
    }

    this.state.showSpinner = false;
    const response: RegistrationResponse | null = this.service.registrationResponse;
    if (response === null) {
      // The purchase is redeemed and still owned by this app; account creation
      // is a separate, retryable step that never charges again.
      this.state.purchaseResult = SignalLoginPurchaseResult.Redeemed;
      this.state.hasUnredeemedPurchase = true;
      this.state.isPurchaseOptionEnabled = true;
      this.state.isActionEnabled = true;
      this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
      this.recordState();
      return;
    }
    this.registerFromReceiptCredential(credential, response);
  }

  /**
   * Creates the account from the verified receipt credential. The store
   * purchase identifier is never the registration credential, and the response
   * decides whether the account is a numberless one.
   */
  private registerFromReceiptCredential(credential: ReceiptCredential, response: RegistrationResponse): void {
    this.effect('registerAccount', {
      'receiptCredential': credential.credential,
      'receiptCredentialRequestContext': credential.receiptCredentialRequestContext,
      'sendsPurchaseTokenAsCredential': false,
      'sendsPhoneNumber': false,
      'e164': response.e164,
      'pni': response.pni,
      'aci': response.aci,
      'storageCapable': response.storageCapable
    } as Record<string, Object>);

    // Numberless is read from the registration response, never assumed from the
    // request, so a response that carried an E.164 can never pass as numberless.
    const numberless: boolean = response.isPhoneNumberless();
    this.state.flow.aci = response.aci;
    this.state.flow.accountEntropyPool = response.accountEntropyPool;
    this.state.flow.e164 = response.e164;
    this.state.flow.pni = response.pni;
    this.state.flow.storageCapable = response.storageCapable;
    this.state.flow.isPhoneNumberlessAccount = numberless;
    this.state.committedAccount.e164 = response.e164;
    this.state.committedAccount.pni = response.pni;
    this.state.committedAccount.pniRegistrationId = null;

    // The purchase is consumed exactly once, and only now that the account it
    // paid for exists. Its persisted context is dropped in the same step.
    const context: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
    if (this.service.consumePurchaseSucceeds && context !== null) {
      this.effect('consumePurchase', { 'purchaseToken': context.purchaseToken } as Record<string, Object>);
      this.state.hasUnredeemedPurchase = false;
      this.clearPurchaseContext();
    }

    this.effect('emitRegistrationFlowEvent.Registered', {
      'aci': response.aci,
      'accountEntropyPool': response.accountEntropyPool,
      'isPhoneNumberlessAccount': numberless
    } as Record<string, Object>);

    this.state.restoreDecision = RestoreDecision.NewAccount;
    this.state.purchaseResult = SignalLoginPurchaseResult.Registered;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Success;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.showSpinner = false;
    this.recordState();

    this.openSignalLoginInfo();
  }

  private failRedemption(error: string): void {
    this.state.showSpinner = false;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Failure;
    this.state.purchaseResult = SignalLoginPurchaseResult.Failed;
    this.state.purchaseError = error;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.dialogs.purchaseFailed = true;
    this.state.isPurchaseOptionEnabled = true;
    this.state.isActionEnabled = true;
    // The purchase stays owned and its context stays persisted, so retrying
    // reuses it rather than charging again.
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.recordState();
  }

  /** Drops the paid purchase context once it has been consumed. */
  private clearPurchaseContext(): void {
    this.state.inProgressRegistrationData.signalLoginPurchase = null;
    this.state.persistedSignalLoginPurchase = null;
    const owned: BillingPurchase | null = this.billing.ownedPurchase;
    if (owned !== null) {
      owned.state = BillingPurchaseState.Consumed;
      this.billing.ownedPurchase = owned;
    }
    this.effect('clearPersistedSignalLoginPurchase', {} as Record<string, Object>);
  }

  /* --------------------------------------------------------- navigation */

  private pushRoute(route: string): void {
    this.state.backStack = [this.state.route];
    this.state.route = route;
    this.effect('navigate', { 'route': route } as Record<string, Object>);
    this.recordState();
  }

  /**
   * Opens the login information screen.
   *
   * The pre-registration back stack is cleared here: once the account exists
   * there is nothing to go back to, and no phone verification or PIN step is
   * inserted anywhere, because a numberless account has neither.
   */
  private openSignalLoginInfo(): void {
    this.state.route = RegistrationRoute.SignalLoginInfo;
    this.state.backStack = [];
    this.state.showSpinner = false;
    this.effect('navigate', {
      'route': RegistrationRoute.SignalLoginInfo,
      'clearedBackStack': true,
      'insertedRoutes': []
    } as Record<string, Object>);
    this.recordState();
  }

  /**
   * Advances past credential preservation. Registration does not reach the
   * username step until the issued account identifier and recovery key have
   * been confirmed.
   */
  private completeCredentialPreservation(): void {
    this.state.savedCredentialConfirmed = true;
    this.state.route = RegistrationRoute.AddUsername;
    this.state.backStack = [];
    this.effect('navigate', {
      'route': RegistrationRoute.AddUsername,
      'clearedBackStack': true
    } as Record<string, Object>);
    this.recordState();
  }

  /* ---------------------------------------------- password manager pathway */

  /**
   * Offers the issued login to the platform password manager. This is the work
   * the navigation collector does while leaving the login screen, and the
   * outcome is routed straight back to the screen that owns the state.
   */
  saveCredentialForReadback(): void {
    if (this.credentialManager.isAvailable() === false) {
      this.state.dialogs.saveFailed = true;
      this.state.showSpinner = false;
      this.state.showConfirmSavedSheet = false;
      this.effect('saveCredentialToPasswordManager', { 'available': false } as Record<string, Object>);
      this.recordState();
      return;
    }
    const accountId: string = this.state.flow.aci;
    const recoveryKey: string = this.state.flow.accountEntropyPool;
    this.effect('saveCredentialToPasswordManager', {
      'username': normalizeAccountId(accountId),
      'password': recoveryKey,
      'routedTo': 'SignalLoginInfoViewModel'
    } as Record<string, Object>);
    this.credentialManager.saveCredential(accountId, recoveryKey);
    this.state.showSpinner = true;
    this.state.isReadbackRequested = true;
    this.state.showConfirmSavedSheet = true;
    this.state.savedCredentialConfirmed = false;
    this.state.dialogs.saveFailed = false;
    this.state.dialogs.saveNotConfirmed = false;
    this.recordState();
  }

  /**
   * The read-back of the saved credential came back. A save is not trusted on
   * its own: the credential is filtered by this account, its username is
   * normalized to an account identifier and its password parsed as a recovery
   * key, and only an exact two part match counts as safely stored.
   */
  completePasswordManagerReadback(): void {
    const accountId: string = this.state.flow.aci;
    this.state.showSpinner = true;
    this.effect('getCredentialFromPasswordManager', {
      'accountId': normalizeAccountId(accountId)
    } as Record<string, Object>);

    const readBack: UsernamePasswordCredential | null = this.credentialManager.getCredential(accountId);
    if (readBack === null) {
      this.failReadback();
      return;
    }
    const matched: boolean = credentialMatches(accountId, this.state.flow.accountEntropyPool, readBack.username, readBack.password);
    this.effect('compareReadBackCredential', {
      'type': readBack.type,
      'accountIdMatches': normalizeAccountId(readBack.username) === normalizeAccountId(accountId),
      'recoveryKeyMatches': matched,
      'confirmed': matched
    } as Record<string, Object>);
    if (matched === false) {
      this.failReadback();
      return;
    }
    this.state.dialogs.saveNotConfirmed = false;
    this.state.dialogs.saveFailed = false;
    this.state.showConfirmSavedSheet = false;
    this.state.showSpinner = false;
    this.recordState();
    this.completeCredentialPreservation();
  }

  /**
   * The saved credential could not be confirmed. The user stays on the login
   * screen and can either save again or record the credential by hand.
   */
  private failReadback(): void {
    this.state.showSpinner = false;
    this.state.showConfirmSavedSheet = false;
    this.state.savedCredentialConfirmed = false;
    this.state.dialogs.saveNotConfirmed = true;
    this.state.route = RegistrationRoute.SignalLoginInfo;
    this.recordState();
  }

  /* ------------------------------------------------------- manual recording */

  /** Opens the manual preservation path. */
  startManualCredentialEntry(): void {
    this.state.route = RegistrationRoute.SignalLoginManualSaveConfirmation;
    this.state.mode = SignalLoginCredentialEntryMode.Enter;
    this.state.enteredAccountId = '';
    this.state.enteredRecoveryKey = '';
    this.state.areCredentialsIncorrect = false;
    this.state.accountIdFieldIncorrect = false;
    this.state.recoveryKeyFieldIncorrect = false;
    this.state.isNextEnabled = false;
    this.effect('navigate', { 'route': RegistrationRoute.SignalLoginManualSaveConfirmation } as Record<string, Object>);
    this.recordState();
  }

  /**
   * Records an edit to one of the two credential halves. Editing either half
   * clears the incorrect flag, so a mistyped credential stays editable and a
   * corrected retry is reachable without recreating the account.
   */
  updateManualCredentialField(field: string, value: string): void {
    if (field === 'accountId') {
      this.state.enteredAccountId = value;
      this.state.accountIdFieldIncorrect = false;
    } else {
      this.state.enteredRecoveryKey = value;
      this.state.recoveryKeyFieldIncorrect = false;
    }
    this.state.areCredentialsIncorrect = false;
    this.state.isNextEnabled = value.length > 0;
    this.recordState();
  }

  /**
   * Confirms a manually recorded login. Both halves are compared with the
   * account material the registration flow already holds; a mismatch flags both
   * fields, because either half may have been copied wrongly.
   */
  submitManualSaveConfirmation(): void {
    this.effect('compareEnteredCredential', {
      'comparedAgainst': 'RegistrationFlowState',
      'comparedAccountId': true,
      'comparedRecoveryKey': true
    } as Record<string, Object>);
    const matched: boolean = credentialMatches(
      this.state.flow.aci,
      this.state.flow.accountEntropyPool,
      this.state.enteredAccountId,
      this.state.enteredRecoveryKey
    );
    if (matched === false) {
      this.state.areCredentialsIncorrect = true;
      this.state.accountIdFieldIncorrect = true;
      this.state.recoveryKeyFieldIncorrect = true;
      this.state.isNextEnabled = true;
      this.state.savedCredentialConfirmed = false;
      this.effect('manualSaveConfirmationRejected', {
        'staysOnRoute': RegistrationRoute.SignalLoginManualSaveConfirmation
      } as Record<string, Object>);
      this.recordState();
      return;
    }
    this.state.areCredentialsIncorrect = false;
    this.state.accountIdFieldIncorrect = false;
    this.state.recoveryKeyFieldIncorrect = false;
    this.state.isNextEnabled = true;
    this.state.savedCredentialConfirmed = true;
    this.state.mode = SignalLoginCredentialEntryMode.ConfirmSaved;
    this.effect('emitRegistrationFlowEvent.AccountCredentialRecorded', {} as Record<string, Object>);
    this.recordState();
    this.completeCredentialPreservation();
  }

  /* --------------------------------------------------------------- username */

  /** The username draft changed. */
  changeUsername(value: string): void {
    this.cancelReservationSettle();
    this.state.username = value;
    this.state.reservation = null;
    this.state.validationError = null;
    this.state.isSubmittable = false;
    if (value.length === 0) {
      this.state.isReserving = false;
      this.recordState();
      return;
    }
    if (this.state.discriminator.length > 0 && this.state.discriminatorFieldFocused === false) {
      this.requestUserChosenReservation();
      return;
    }
    this.recordState();
  }

  /** The discriminator field gained focus. */
  focusDiscriminator(): void {
    this.cancelReservationSettle();
    this.state.discriminatorFieldFocused = true;
    this.state.isReserving = false;
    this.recordState();
  }

  /**
   * The discriminator changed. Typing a discriminator reserves the exact
   * pairing the user asked for once they stop; clearing it drops that pairing,
   * because a reservation for digits the screen no longer holds can never be
   * confirmed.
   */
  changeDiscriminator(value: string): void {
    if (value.length === 0) {
      this.clearUserChosenDiscriminator();
      return;
    }
    this.cancelReservationSettle();
    this.state.discriminator = value;
    this.state.isDiscriminatorUserSet = true;
    this.state.validationError = null;
    this.state.isSubmittable = false;
    this.state.isReserving = true;
    this.recordState();
    this.scheduleReservationSettle();
  }

  /**
   * Clears a user chosen discriminator. The exact reservation made for the
   * erased pairing is invalidated immediately and cannot be confirmed, and no
   * fresh reservation is asked for until the field loses focus.
   */
  clearUserChosenDiscriminator(): void {
    this.cancelReservationSettle();
    this.state.discriminator = '';
    this.state.isDiscriminatorUserSet = false;
    this.state.reservation = null;
    this.state.validationError = null;
    this.state.isReserving = false;
    this.state.isSubmittable = false;
    this.recordState();
  }

  /** The discriminator field lost focus, so reservations may start again. */
  loseDiscriminatorFocus(): void {
    this.state.discriminatorFieldFocused = false;
    this.cancelReservationSettle();
    if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0 && this.state.reservation !== null) {
      this.state.isSubmittable = this.state.username.length > 0;
      this.recordState();
      return;
    }
    this.requestServiceAssignedReservation();
  }

  private scheduleReservationSettle(): void {
    this.settleHandle = setTimeout(() => {
      this.settleHandle = 0;
      this.settleReservation();
    }, RESERVATION_SETTLE_MILLISECONDS);
  }

  private cancelReservationSettle(): void {
    if (this.settleHandle !== 0) {
      clearTimeout(this.settleHandle);
      this.settleHandle = 0;
    }
  }

  /**
   * Runs after the user stopped typing. A reservation is never requested while
   * the field still has focus, because the response would race an edit that has
   * not reached the flow yet.
   */
  private settleReservation(): void {
    if (this.state.discriminatorFieldFocused) {
      this.state.isReserving = false;
      return;
    }
    if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0) {
      this.requestUserChosenReservation();
      return;
    }
    this.requestServiceAssignedReservation();
  }

  private requestUserChosenReservation(): void {
    const username: string = this.state.username;
    if (username.length === 0) {
      this.state.isReserving = false;
      this.state.isSubmittable = false;
      this.recordState();
      return;
    }
    const reservation: string = username + '.' + this.state.discriminator;
    const validationError: string = this.service.serviceUsernameValidationError;
    this.effect('reserveUsername.' + username + '.userChosen', {
      'reservation': reservation,
      'validationError': validationError
    } as Record<string, Object>);
    this.applyReservation(reservation, validationError);
  }

  private requestServiceAssignedReservation(): void {
    const username: string = this.state.username;
    if (username.length === 0) {
      this.state.isReserving = false;
      this.state.isSubmittable = false;
      this.recordState();
      return;
    }
    const assigned: string = this.service.serviceAssignedReservation.length > 0 ? this.service.serviceAssignedReservation : username;
    const validationError: string = this.service.serviceUsernameValidationError;
    this.effect('reserveUsername.' + username + '.serviceAssigned', {
      'reservation': assigned,
      'validationError': validationError
    } as Record<string, Object>);
    this.applyReservation(assigned, validationError);
  }

  /** A reservation failure stays retryable and never discards the current draft. */
  private applyReservation(reservation: string, validationError: string): void {
    this.state.isReserving = false;
    this.state.isDiscriminatorUserSet = this.state.discriminator.length > 0;
    if (validationError.length > 0) {
      this.state.reservation = null;
      this.state.validationError = validationError;
      this.state.isSubmittable = false;
      this.recordState();
      return;
    }
    this.state.reservation = reservation;
    this.state.validationError = null;
    this.state.isSubmittable = this.state.username.length > 0;
    this.recordState();
  }

  /** The reservation failed and the user asked to try again. */
  retryUsernameReservation(): void {
    if (this.state.username.length === 0) {
      return;
    }
    if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0) {
      this.requestUserChosenReservation();
      return;
    }
    this.requestServiceAssignedReservation();
  }

  /**
   * The user asked to continue without a username. This is only a request: the
   * flow stays on the username screen and registration stays incomplete until
   * the request is confirmed.
   */
  requestUsernameSkip(): void {
    this.state.dialogs.confirmSkip = true;
    this.state.registrationComplete = false;
    this.state.finalRegistrationCommitted = false;
    this.recordState();
  }

  /** The skip confirmation was dismissed, so the username draft is still editable. */
  dismissUsernameSkipConfirmation(): void {
    this.state.dialogs.confirmSkip = false;
    this.state.registrationComplete = false;
    this.state.finalRegistrationCommitted = false;
    this.recordState();
  }

  /** The skip confirmation was accepted, which is the only way to skip. */
  confirmUsernameSkip(): void {
    if (this.state.dialogs.confirmSkip === false) {
      return;
    }
    this.effect('emitRegistrationFlowEvent.RegistrationComplete', {
      'username': '',
      'skippedUsername': true
    } as Record<string, Object>);
    this.state.dialogs.confirmSkip = false;
    this.state.registrationComplete = true;
    this.state.finalRegistrationCommitted = true;
    this.state.isSubmittable = false;
    this.state.route = RegistrationRoute.FullyComplete;
    this.state.flow.username = null;
    this.effect('navigate', { 'route': RegistrationRoute.FullyComplete } as Record<string, Object>);
    this.recordState();
  }

  /** The reserved username was confirmed and registration completes. */
  confirmUsername(): void {
    if (this.state.isSubmittable === false || this.state.reservation === null) {
      return;
    }
    this.effect('emitRegistrationFlowEvent.RegistrationComplete', {
      'username': this.state.username,
      'reservation': this.state.reservation as string
    } as Record<string, Object>);
    this.state.dialogs.confirmSkip = false;
    this.state.registrationComplete = true;
    this.state.finalRegistrationCommitted = true;
    this.state.route = RegistrationRoute.FullyComplete;
    this.state.flow.username = this.state.username;
    this.effect('navigate', { 'route': RegistrationRoute.FullyComplete } as Record<string, Object>);
    this.recordState();
  }

  /* ------------------------------------------------------------ accessors */

  currentState(): Record<string, Object> {
    return this.snapshot();
  }

  registrationSnapshot(): Record<string, Object> {
    return this.registrationData;
  }

  /** Records the purchase the app paid for so it survives a process recreation. */
  rememberPaidPurchase(context: SignalLoginPurchaseContext): void {
    this.state.inProgressRegistrationData.signalLoginPurchase = context;
    this.state.persistedSignalLoginPurchase = context;
    this.state.hasUnredeemedPurchase = true;
    const productId: string = this.service.loginConfiguration.playProductId;
    this.billing.ownedPurchase = new BillingPurchase(context.purchaseToken, BillingPurchaseState.Purchased);
    this.billing.product = new BillingProductOption(productId, context.purchaseOptionId, context.formattedPrice);
  }

  /** Restores a paid purchase context that was read back out of durable storage. */
  restorePaidPurchase(context: SignalLoginPurchaseContext): void {
    this.state.inProgressRegistrationData.signalLoginPurchase = context;
    this.state.persistedSignalLoginPurchase = context;
    this.state.hasUnredeemedPurchase = true;
    this.billing.ownedPurchase = new BillingPurchase(context.purchaseToken, BillingPurchaseState.Purchased);
  }
}

function asOptionalIdentity(value: Object | undefined): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  const text: string = asText(value);
  return text.length === 0 ? null : text;
}

/** Configuration the service exposes for the username screens. */
export class SignalServiceSnapshotExtension {
  serviceUsernameValidationError: string = '';
}

metadata.rawInput:
{"content":"/**
 * The registration flow that lets a new user create a Signal account without
 * supplying a phone number.
 *
 * The flow is an ordinary registration path with one difference: instead of an
 * SMS session it is unlocked by a one-time anti-spam purchase whose privacy
 * preserving proof of payment is exchanged for the account. Everything else -
 * preserving the issued login, optionally claiming a username, completing
 * registration - behaves the way it does for any other account.
 *
 * The flow owns state and decisions only. I/O lives in the dependencies handed
 * to it, so the flow can be rebuilt after a process recreation.
 */
import {
  BillingProductOption,
  BillingPurchase,
  BillingPurchaseState,
  BillingSnapshot,
  OneTimePurchaseOutcome,
  OneTimePurchasePreparation,
  OneTimePurchaseRequest,
  PaymentAvailability,
  isTerminalAvailability
} from './Billing';
import {
  CreateLoginReceiptCredentialResult,
  LoginConfiguration,
  ReceiptCredential,
  ReceiptCredentialVerification,
  RegistrationResponse,
  RestoreDecision,
  SignalServiceSnapshot
} from './SignalService';
import {
  SignalCredentialManager,
  UsernamePasswordCredential,
  credentialMatches,
  normalizeAccountId
} from './CredentialManager';
import { asFlag, asFlagOr, asRecord, asText, asTextOr, isEmptyRecord } from './Json';

/* ------------------------------------------------------------------ routes */

/** Destination of the registration flow. */
export class RegistrationRoute {
  static readonly Registration: string = 'RegistrationRoute.Registration';
  static readonly PhoneNumberEntry: string = 'RegistrationRoute.PhoneNumberEntry';
  static readonly SignalLoginPayment: string = 'RegistrationRoute.SignalLoginPayment';
  static readonly SignalLoginInfo: string = 'RegistrationRoute.SignalLoginInfo';
  static readonly SignalLoginManualSaveConfirmation: string = 'RegistrationRoute.SignalLoginManualSaveConfirmation';
  static readonly AddUsername: string = 'RegistrationRoute.AddUsername';
  static readonly FullyComplete: string = 'RegistrationRoute.FullyComplete';
}

/** Outcome of the one-time purchase, as the payment screen reports it. */
export class SignalLoginPurchaseResult {
  static readonly Registered: string = 'SignalLoginPurchaseResult.Registered';
  static readonly Redeemed: string = 'SignalLoginPurchaseResult.Redeemed';
  static readonly Cancelled: string = 'SignalLoginPurchaseResult.Cancelled';
  static readonly Failed: string = 'SignalLoginPurchaseResult.Failed';
}

/** Price states of the payment screen. */
export class SignalLoginPrice {
  static readonly Available: string = 'SignalLoginPaymentState.Price.Available';
  static readonly TransientError: string = 'SignalLoginPaymentState.Price.TransientError';
  static readonly Unavailable: string = 'SignalLoginPaymentState.Price.Unavailable';
}

/** Options of the payment screen. */
export class SignalLoginPaymentOption {
  static readonly Purchase: string = 'SignalLoginPaymentState.Option.Purchase';
}

/** Modes of the manual credential entry screen. */
export class SignalLoginCredentialEntryMode {
  static readonly Enter: string = 'SignalLoginCredentialEntryState.Mode.Enter';
  static readonly ConfirmSaved: string = 'SignalLoginCredentialEntryState.Mode.ConfirmSaved';
}

/** Errors the payment screen can report while keeping the purchase recoverable. */
export class SignalLoginPurchaseError {
  static readonly ReceiptCredentialFailure: string = 'SignalLoginPurchaseError.ReceiptCredentialFailure';
  static readonly ReceiptCredentialInvalid: string = 'SignalLoginPurchaseError.ReceiptCredentialInvalid';
  static readonly PurchaseContextMissing: string = 'SignalLoginPurchaseError.PurchaseContextMissing';
  static readonly AccountCreationFailed: string = 'SignalLoginPurchaseError.AccountCreationFailed';
}

/** Milliseconds the username screens wait before asking the service to reserve. */
export const RESERVATION_SETTLE_MILLISECONDS: number = 500;

/* ------------------------------------------------------------------- state */

/** Price as the payment screen renders it. */
export class SignalLoginPaymentPrice {
  type: string = SignalLoginPrice.Unavailable;
  formattedPrice: string = '';
}

/** Dialogs the payment screen can raise. */
export class SignalLoginPaymentDialogs {
  paymentUnavailable: boolean = false;
  purchaseFailed: boolean = false;
  saveNotConfirmed: boolean = false;
  saveFailed: boolean = false;
  confirmSkip: boolean = false;
}

/** Account material the registration flow holds after account creation. */
export class AccountFlowState {
  aci: string = '';
  accountEntropyPool: string = '';
  e164: string | null = null;
  pni: string | null = null;
  storageCapable: boolean = false;
  isPhoneNumberlessAccount: boolean = false;
  username: string | null = null;
}

/** Identity the app committed to disk when the account was created. */
export class CommittedAccount {
  e164: string | null = null;
  pni: string | null = null;
  pniRegistrationId: number | null = null;
}

/**
 * The purchase the app has paid for but not yet redeemed, together with the
 * receipt credential request context the service must be asked about again. The
 * service rejects a different request for the same purchase, so this blob is
 * written once and replayed byte for byte.
 */
export class SignalLoginPurchaseContext {
  purchaseToken: string = '';
  receiptCredentialRequestContext: string = '';
  productId: string = '';
  purchaseOptionId: string = '';
  formattedPrice: string = '';

  constructor(purchaseToken: string, receiptCredentialRequestContext: string) {
    this.purchaseToken = purchaseToken;
    this.receiptCredentialRequestContext = receiptCredentialRequestContext;
  }

  static fromJson(value: Record<string, Object>): SignalLoginPurchaseContext {
    const context = new SignalLoginPurchaseContext(asText(value['purchaseToken']), asText(value['receiptCredentialRequestContext']));
    context.productId = asText(value['productId']);
    context.purchaseOptionId = asText(value['purchaseOptionId']);
    context.formattedPrice = asText(value['formattedPrice']);
    return context;
  }
}

/** In-progress registration data the app keeps across a process recreation. */
export class InProgressRegistrationData {
  signalLoginPurchase: SignalLoginPurchaseContext | null = null;
}

/** The complete registration state of phone-numberless registration. */
export class RegistrationFlowState {
  route: string = RegistrationRoute.Registration;
  backStack: string[] = [];

  numberlessRegistrationAvailable: boolean = true;
  numberlessRegistrationEnabled: boolean = false;
  phoneNumberRegistrationEnabled: boolean = true;

  selectedOption: string = SignalLoginPaymentOption.Purchase;
  paymentAvailability: string = PaymentAvailability.Unavailable;
  price: SignalLoginPaymentPrice = new SignalLoginPaymentPrice();
  isPriceLoading: boolean = false;
  showSpinner: boolean = false;
  hasUnredeemedPurchase: boolean = false;
  purchasePreparation: string = OneTimePurchasePreparation.Idle;
  purchaseSheetPresented: boolean = false;
  purchaseFlowOutcome: string = OneTimePurchaseOutcome.Unresolved;
  purchaseResult: string = '';
  purchaseError: string = '';
  isPurchaseOptionEnabled: boolean = false;
  isActionEnabled: boolean = false;
  dialogs: SignalLoginPaymentDialogs = new SignalLoginPaymentDialogs();

  flow: AccountFlowState = new AccountFlowState();
  committedAccount: CommittedAccount = new CommittedAccount();
  restoreDecision: string = '';
  inProgressRegistrationData: InProgressRegistrationData = new InProgressRegistrationData();

  isPasswordManagerAvailable: boolean = false;
  showConfirmSavedSheet: boolean = false;
  savedCredentialConfirmed: boolean = false;
  isReadbackRequested: boolean = false;

  mode: string = SignalLoginCredentialEntryMode.ConfirmSaved;
  enteredAccountId: string = '';
  enteredRecoveryKey: string = '';
  areCredentialsIncorrect: boolean = false;
  accountIdFieldIncorrect: boolean = false;
  recoveryKeyFieldIncorrect: boolean = false;
  isNextEnabled: boolean = false;

  username: string = '';
  discriminator: string = '';
  isDiscriminatorUserSet: boolean = false;
  reservation: string | null = null;
  validationError: string | null = null;
  isReserving: boolean = false;
  isSubmittable: boolean = false;
  discriminatorFieldFocused: boolean = false;

  registrationComplete: boolean = false;
  finalRegistrationCommitted: boolean = false;

  persistedSignalLoginPurchase: SignalLoginPurchaseContext | null = null;
}

/* ------------------------------------------------------------- observation */

/**
 * Where the flow reports the decisions it takes. Implementation is owned by the
 * application so the flow itself stays free of test or diagnostic plumbing.
 */
export interface RegistrationFlowObserver {
  recordEffect(json: string): void;

  recordState(snapshotJson: string): void;
}

/* ------------------------------------------------------------------- flow */

/** Owns the state and the decisions of phone-numberless registration. */
export class NumberlessRegistrationFlow {
  private state: RegistrationFlowState = new RegistrationFlowState();
  private billing: BillingSnapshot;
  private service: SignalServiceSnapshot;
  private credentialManager: SignalCredentialManager;
  private observer: RegistrationFlowObserver;
  private sheet: OneTimePurchaseSheet | null = null;
  private registrationData: Record<string, Object> = {} as Record<string, Object>;
  private settleHandle: number = 0;

  constructor(
    billing: BillingSnapshot,
    service: SignalServiceSnapshot,
    credentialManager: SignalCredentialManager,
    observer: RegistrationFlowObserver,
    sheet: OneTimePurchaseSheet | null
  ) {
    this.billing = billing;
    this.service = service;
    this.credentialManager = credentialManager;
    this.observer = observer;
    this.sheet = sheet;
  }

  /* ----------------------------------------------------------- hydration */

  /**
   * Rebuilds the flow from the application owned registration data plus the
   * state the external services are known to be in. Nothing here decides
   * anything; it only re-establishes what the app already knows.
   */
  restore(registrationData: Record<string, Object>): void {
    this.registrationData = registrationData;
    this.state = new RegistrationFlowState();
    this.billing = new BillingSnapshot();
    this.service = new SignalServiceSnapshot();
    this.hydrate(registrationData);
  }

  private hydrate(given: Record<string, Object>): void {
    const payment: Record<string, Object> = asRecord(given['payment']);
    const flow: Record<string, Object> = asRecord(given['flow']);
    const parentLogin: Record<string, Object> = asRecord(given['parentLogin']);
    const entered: Record<string, Object> = asRecord(given['enteredLogin']);
    const dialogs: Record<string, Object> = asRecord(given['dialogs']);

    this.state.route = asTextOr(asTextOr(given['route'], asTextOr(given['entryRoute'], this.state.route)), this.state.route);
    this.state.numberlessRegistrationAvailable = asFlagOr(given['phoneNumberlessRegistrationAvailable'], true);
    this.state.numberlessRegistrationEnabled = this.state.numberlessRegistrationAvailable;

    this.state.selectedOption = asTextOr(given['selectedOption'], this.state.selectedOption);
    this.state.paymentAvailability = asTextOr(given['paymentAvailability'], asTextOr(given['googlePlayServices'], this.state.paymentAvailability));
    this.hydratePrice(asRecord(given['price']), asTextOr(given['price'], ''));
    this.state.showSpinner = asFlagOr(given['showSpinner'], asFlag(payment['showSpinner']));
    this.state.purchasePreparation = asTextOr(given['purchasePreparation'], this.state.purchasePreparation);
    this.state.purchaseSheetPresented = asText(given['purchaseSheet']) === 'open';
    this.state.hasUnredeemedPurchase = asFlag(given['hasUnredeemedPurchase']) || asFlag(payment['hasUnredeemedPurchase']) || asFlag(given['ownedUnconsumedPurchase']);

    this.state.dialogs.paymentUnavailable = asFlag(dialogs['paymentUnavailable']);
    this.state.dialogs.purchaseFailed = asFlag(dialogs['purchaseFailed']);
    this.state.dialogs.saveNotConfirmed = asFlag(dialogs['saveNotConfirmed']);
    this.state.dialogs.saveFailed = asFlag(dialogs['saveFailed']);
    this.state.dialogs.confirmSkip = asFlag(dialogs['confirmSkip']);

    this.state.flow.aci = asTextOr(flow['aci'], asTextOr(given['aci'], asTextOr(parentLogin['aci'], this.state.flow.aci)));
    this.state.flow.accountEntropyPool = asTextOr(flow['accountEntropyPool'], asTextOr(given['accountEntropyPool'], asTextOr(parentLogin['accountEntropyPool'], this.state.flow.accountEntropyPool)));
    this.state.flow.e164 = asOptionalIdentity(flow['e164']);
    this.state.flow.pni = asOptionalIdentity(flow['pni']);
    this.state.flow.storageCapable = asFlagOr(flow['storageCapable'], this.state.flow.storageCapable);
    this.state.flow.isPhoneNumberlessAccount = asFlagOr(flow['isPhoneNumberlessAccount'], this.state.flow.isPhoneNumberlessAccount);

    this.state.mode = asTextOr(given['mode'], this.state.mode);
    this.state.enteredAccountId = asText(entered['accountId']);
    this.state.enteredRecoveryKey = asText(entered['recoveryKey']);
    this.state.areCredentialsIncorrect = asFlag(given['areCredentialsIncorrect']);
    this.state.isNextEnabled = asFlag(given['isNextEnabled']);

    this.state.isPasswordManagerAvailable = asFlagOr(given['isPasswordManagerAvailable'], this.credentialManager.isAvailable());
    this.state.showConfirmSavedSheet = asFlag(given['showConfirmSavedSheet']);
    this.state.isReadbackRequested = asText(given['readbackRequest']) === 'held';

    this.state.username = asText(given['username']);
    this.state.discriminator = asText(given['discriminator']);
    this.state.isDiscriminatorUserSet = asFlag(given['isDiscriminatorUserSet']);
    this.state.reservation = asOptionalIdentity(given['reservation']);
    this.state.validationError = asOptionalIdentity(given['validationError']);
    this.state.isReserving = asFlag(given['isReserving']);
    this.state.isSubmittable = asFlag(given['isSubmittable']);
    this.state.discriminatorFieldFocused = asFlag(given['discriminatorFieldFocused']);

    this.state.registrationComplete = asFlag(given['registrationComplete']);
    this.state.finalRegistrationCommitted = asFlag(given['finalRegistrationCommitted']);

    this.billing.restore(given);
    if (isEmptyRecord(asRecord(given['ownedPurchase'])) === false) {
      // already handled by the billing snapshot
    }
    const purchase: Record<string, Object> = asRecord(given['purchase']);
    if (isEmptyRecord(purchase) === false) {
      this.billing.ownedPurchase = BillingPurchase.fromJson(purchase);
    }
    if (this.billing.hasOwnedUnredeemedPurchase()) {
      this.state.hasUnredeemedPurchase = true;
    }
    this.service.restore(given);
    this.state.paymentAvailability = asTextOr(given['paymentAvailability'], this.state.paymentAvailability);

    const persisted: Record<string, Object> = asRecord(given['persistedSignalLoginPurchase']);
    if (isEmptyRecord(persisted) === false) {
      this.state.persistedSignalLoginPurchase = SignalLoginPurchaseContext.fromJson(persisted);
      this.state.inProgressRegistrationData.signalLoginPurchase = this.state.persistedSignalLoginPurchase;
    }

    const readback: Record<string, Object> = asRecord(given['readbackCredential']);
    const retrieved: Record<string, Object> = asRecord(given['savedCredentialRetrieved']);
    const stored: Record<string, Object> = asRecord(given['passwordManagerStoredCredential']);
    if (isEmptyRecord(readback) === false) {
      this.credentialManager.seed(UsernamePasswordCredential.fromJson(readback));
    } else if (isEmptyRecord(retrieved) === false) {
      this.credentialManager.seed(UsernamePasswordCredential.fromJson(retrieved));
    } else if (isEmptyRecord(stored) === false) {
      this.credentialManager.seed(UsernamePasswordCredential.fromJson(stored));
    }
  }

  private hydratePrice(price: Record<string, Object>, fallbackType: string): void {
    if (isEmptyRecord(price)) {
      this.state.price.type = fallbackType.length > 0 ? fallbackType : SignalLoginPrice.Unavailable;
      return;
    }
    this.state.price.type = asTextOr(price['type'], SignalLoginPrice.Unavailable);
    this.state.price.formattedPrice = asText(price['formattedPrice']);
  }

  /* --------------------------------------------------------- observation */

  private snapshot(): Record<string, Object> {
    return JSON.parse(JSON.stringify(this.state)) as Record<string, Object>;
  }

  private recordState(): void {
    this.observer.recordState(JSON.stringify(this.state));
  }

  private effect(name: string, detail: Record<string, Object>): void {
    const payload: Record<string, Object> = detail;
    payload['name'] = name;
    this.observer.recordEffect(JSON.stringify(payload));
  }

  /* ------------------------------------------------------ entry selection */

  /** Chooses the ordinary phone number path. It is always offered. */
  startPhoneNumberRegistration(): void {
    this.state.phoneNumberRegistrationEnabled = true;
    this.pushRoute(RegistrationRoute.PhoneNumberEntry);
  }

  /**
   * Chooses registration without a phone number. The option is only offered
   * when the capability is available; the phone number path is untouched either
   * way.
   */
  startRegistrationWithoutNumber(): void {
    if (this.state.numberlessRegistrationAvailable === false) {
      return;
    }
    this.state.numberlessRegistrationEnabled = true;
    this.state.route = RegistrationRoute.SignalLoginPayment;
    this.state.backStack = [RegistrationRoute.Registration];
  }

  /* --------------------------------------------------------- price loading */

  /**
   * Loads the anti-spam purchase price.
   *
   * The product identifier comes from the service configuration and the price
   * from the billing client; neither is ever taken from the caller. Loading the
   * price never starts or completes a purchase.
   */
  initializeSignalLoginPayment(): void {
    if (this.state.numberlessRegistrationAvailable === false) {
      return;
    }
    this.state.route = RegistrationRoute.SignalLoginPayment;
    this.state.selectedOption = SignalLoginPaymentOption.Purchase;
    this.state.numberlessRegistrationEnabled = true;
    this.state.purchaseResult = '';
    this.state.purchaseError = '';
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
    this.state.purchaseSheetPresented = false;
    this.state.isPriceLoading = true;
    this.state.showSpinner = true;
    this.recordState();

    this.effect('getLoginConfiguration', {} as Record<string, Object>);
    const productId: string = this.service.loginConfiguration.playProductId;
    this.effect('queryBillingProduct', { 'productId': productId } as Record<string, Object>);

    this.state.paymentAvailability = this.billing.availability();
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.applyPrice(productId, this.billing.product);

    const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.isPurchaseOptionEnabled = terminal === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled && (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
    this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
    this.state.dialogs.paymentUnavailable = terminal;
    this.state.isPriceLoading = false;
    this.state.showSpinner = false;
    this.recordState();
  }

  /**
   * Re-runs the price lookup. Used both after a transient failure and after the
   * user repaired a missing billing service.
   */
  reloadSignalLoginPaymentPrice(): void {
    if (this.state.numberlessRegistrationAvailable === false) {
      return;
    }
    this.state.isPriceLoading = true;
    this.state.showSpinner = true;
    this.recordState();

    this.effect('queryBillingProduct', { 'productId': this.service.loginConfiguration.playProductId } as Record<string, Object>);
    this.state.paymentAvailability = this.billing.availability();
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.applyPrice(this.service.loginConfiguration.playProductId, this.billing.product);

    const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.isPurchaseOptionEnabled = terminal === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled && (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
    this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
    this.state.dialogs.paymentUnavailable = terminal;
    this.state.isPriceLoading = false;
    this.state.showSpinner = false;
    this.recordState();
  }

  /**
   * Applies a billing price, but only for the product the service named. A
   * price that belongs to some other product is not this app's price and is
   * never displayed as one.
   */
  private applyPrice(productId: string, option: BillingProductOption | null): void {
    if (option === null || productId.length === 0 || option.productId !== productId) {
      const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
      this.state.price.type = terminal ? SignalLoginPrice.Unavailable : SignalLoginPrice.TransientError;
      this.state.price.formattedPrice = '';
      return;
    }
    this.state.price.type = SignalLoginPrice.Available;
    this.state.price.formattedPrice = option.formattedPrice;
  }

  /* ------------------------------------------------------------- purchase */

  /**
   * Acts on the payment screen's primary button.
   *
   * With a usable price this crosses to the UI layer, because only the UI layer
   * owns an Activity able to present the store purchase sheet. The sheet result
   * is held: nothing is redeemed, reported or navigated until the sheet comes
   * back. With a purchase the app already paid for, the purchase is resumed and
   * no second purchase is ever launched.
   */
  continuePurchase(): void {
    if (this.state.hasUnredeemedPurchase) {
      this.resumeOwnedPurchase();
      return;
    }
    if (this.state.isPurchaseOptionEnabled === false || this.state.isActionEnabled === false) {
      return;
    }
    const option: BillingProductOption | null = this.billing.product;
    if (option === null || option.productId !== this.service.loginConfiguration.playProductId) {
      return;
    }
    this.state.purchaseResult = '';
    this.state.purchaseError = '';
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Unresolved;
    this.state.dialogs.purchaseFailed = false;
    this.effect('launchPurchaseFlow', {
      'launchedBy': 'ui',
      'ownsActivity': true,
      'productId': option.productId,
      'purchaseOptionId': option.purchaseOptionId,
      'formattedPrice': option.formattedPrice
    } as Record<string, Object>);

    const request = new OneTimePurchaseRequest(option.productId, option.purchaseOptionId, option.formattedPrice);
    if (this.sheet !== null) {
      this.sheet.present(request);
    }
    this.state.purchaseSheetPresented = true;
    this.state.showSpinner = true;
    this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
    this.recordState();
  }

  /**
   * The store purchase sheet came back without a purchase. Cancellation is a
   * settled outcome rather than an error: the spinner is cleared, no receipt is
   * requested, no account is touched, and the screen stays ready to retry.
   */
  completeCancelledPurchase(): void {
    this.state.purchaseSheetPresented = false;
    this.state.showSpinner = false;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Cancelled;
    this.state.purchaseResult = SignalLoginPurchaseResult.Cancelled;
    this.state.purchaseError = '';
    this.state.dialogs = new SignalLoginPaymentDialogs();
    this.state.dialogs.paymentUnavailable = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.isPurchaseOptionEnabled = this.state.dialogs.paymentUnavailable === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled;
    this.recordState();
  }

  /**
   * The purchase sheet came back with a failure. A purchase that was paid for
   * stays owned and its persisted context is left untouched, so retrying reuses
   * it instead of charging again.
   */
  completeFailedPurchase(): void {
    this.state.purchaseSheetPresented = false;
    this.state.showSpinner = false;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Failure;
    this.state.purchaseResult = SignalLoginPurchaseResult.Failed;
    this.state.purchaseError = SignalLoginPurchaseError.AccountCreationFailed;
    this.state.dialogs.purchaseFailed = true;
    this.state.isPurchaseOptionEnabled = true;
    this.state.isActionEnabled = true;
    this.recordState();
  }

  /**
   * The payment screen came back to the foreground, typically after the user
   * left to repair a billing service the operating system was updating.
   * Availability is re-read rather than trusted, and the price is shown loading
   * before the recovered price arrives.
   */
  foregroundPaymentScreen(): void {
    this.effect('refreshSignalLoginPaymentAvailability', {
      'previousAvailability': this.state.paymentAvailability
    } as Record<string, Object>);
    this.state.isPriceLoading = true;
    this.state.showSpinner = true;
    this.recordState();

    const reported: string = this.registrationData['nextAvailability'];
    if (reported.length > 0) {
      this.billing.googlePlayServices = reported;
      this.billing.billingAvailable = true;
    }
    this.state.paymentAvailability = this.billing.availability();
    this.effect('queryBillingProduct', { 'productId': this.service.loginConfiguration.playProductId } as Record<string, Object>);
    const requeried: string = this.registrationData['nextPrice'];
    if (requeried.length > 0) {
      const productId: string = this.service.loginConfiguration.playProductId;
      const current: BillingProductOption | null = this.billing.product;
      this.billing.product = new BillingProductOption(productId, current !== null ? current.purchaseOptionId : '', requeried);
    }
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.applyPrice(this.service.loginConfiguration.playProductId, this.billing.product);

    const terminal: boolean = isTerminalAvailability(this.state.paymentAvailability as PaymentAvailability);
    this.state.dialogs.paymentUnavailable = terminal;
    this.state.isPurchaseOptionEnabled = terminal === false;
    this.state.isActionEnabled = this.state.isPurchaseOptionEnabled && (this.state.hasUnredeemedPurchase || this.state.price.type === SignalLoginPrice.Available);
    this.state.purchasePreparation = this.state.isActionEnabled ? OneTimePurchasePreparation.Ready : OneTimePurchasePreparation.Idle;
    this.state.isPriceLoading = false;
    this.state.showSpinner = false;
    this.recordState();
  }

  /* ------------------------------------------------------------ redemption */

  /**
   * Resumes a purchase this app already paid for. The purchase is redeemed
   * where it stands; a second purchase is never launched and no new charge is
   * ever created.
   */
  private resumeOwnedPurchase(): void {
    this.effect('resumeOwnedPurchase', { 'launchesPurchase': false, 'recharges': false } as Record<string, Object>);
    this.state.purchaseSheetPresented = false;
    this.state.purchaseResult = '';
    this.state.purchaseError = '';
    this.state.showSpinner = true;
    this.state.purchasePreparation = OneTimePurchasePreparation.Busy;
    this.recordState();
    this.redeemAndRegister();
  }

  /**
   * Exchanges the store purchase for a verified receipt credential and, when
   * the account can be created, creates it. Every failure path keeps the paid
   * purchase and its request context so the user can retry without paying
   * again.
   */
  private redeemAndRegister(): void {
    const context: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
    if (context === null || context.purchaseToken.length === 0) {
      this.failRedemption(SignalLoginPurchaseError.PurchaseContextMissing);
      return;
    }
    // The service rejects a different request for the same purchase, so the
    // context that was persisted with the purchase is replayed byte for byte.
    this.effect('createLoginReceiptCredential', {
      'purchaseToken': context.purchaseToken,
      'receiptCredentialRequestContext': context.receiptCredentialRequestContext,
      'sendsPurchaseTokenAsCredential': false
    } as Record<string, Object>);

    const issuance: string = this.service.nextIssuance();
    if (issuance !== CreateLoginReceiptCredentialResult.Issued) {
      this.failRedemption(SignalLoginPurchaseError.ReceiptCredentialFailure);
      return;
    }
    const credential: ReceiptCredential = new ReceiptCredential(context.receiptCredentialRequestContext, 'receipt-credential-for-' + context.purchaseToken);

    this.effect('verifyReceiptCredential', { 'result': this.service.receiptCredentialVerification } as Record<string, Object>);
    if (this.service.receiptCredentialVerification !== ReceiptCredentialVerification.Success) {
      this.failRedemption(SignalLoginPurchaseError.ReceiptCredentialInvalid);
      return;
    }

    this.state.showSpinner = false;
    const response: RegistrationResponse | null = this.service.registrationResponse;
    if (response === null) {
      // The purchase is redeemed and still owned by this app; account creation
      // is a separate, retryable step that never charges again.
      this.state.purchaseResult = SignalLoginPurchaseResult.Redeemed;
      this.state.hasUnredeemedPurchase = true;
      this.state.isPurchaseOptionEnabled = true;
      this.state.isActionEnabled = true;
      this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
      this.recordState();
      return;
    }
    this.registerFromReceiptCredential(credential, response);
  }

  /**
   * Creates the account from the verified receipt credential. The store
   * purchase identifier is never the registration credential, and the response
   * decides whether the account is a numberless one.
   */
  private registerFromReceiptCredential(credential: ReceiptCredential, response: RegistrationResponse): void {
    this.effect('registerAccount', {
      'receiptCredential': credential.credential,
      'receiptCredentialRequestContext': credential.receiptCredentialRequestContext,
      'sendsPurchaseTokenAsCredential': false,
      'sendsPhoneNumber': false,
      'e164': response.e164,
      'pni': response.pni,
      'aci': response.aci,
      'storageCapable': response.storageCapable
    } as Record<string, Object>);

    // Numberless is read from the registration response, never assumed from the
    // request, so a response that carried an E.164 can never pass as numberless.
    const numberless: boolean = response.isPhoneNumberless();
    this.state.flow.aci = response.aci;
    this.state.flow.accountEntropyPool = response.accountEntropyPool;
    this.state.flow.e164 = response.e164;
    this.state.flow.pni = response.pni;
    this.state.flow.storageCapable = response.storageCapable;
    this.state.flow.isPhoneNumberlessAccount = numberless;
    this.state.committedAccount.e164 = response.e164;
    this.state.committedAccount.pni = response.pni;
    this.state.committedAccount.pniRegistrationId = null;

    // The purchase is consumed exactly once, and only now that the account it
    // paid for exists. Its persisted context is dropped in the same step.
    const context: SignalLoginPurchaseContext | null = this.state.inProgressRegistrationData.signalLoginPurchase;
    if (this.service.consumePurchaseSucceeds && context !== null) {
      this.effect('consumePurchase', { 'purchaseToken': context.purchaseToken } as Record<string, Object>);
      this.state.hasUnredeemedPurchase = false;
      this.clearPurchaseContext();
    }

    this.effect('emitRegistrationFlowEvent.Registered', {
      'aci': response.aci,
      'accountEntropyPool': response.accountEntropyPool,
      'isPhoneNumberlessAccount': numberless
    } as Record<string, Object>);

    this.state.restoreDecision = RestoreDecision.NewAccount;
    this.state.purchaseResult = SignalLoginPurchaseResult.Registered;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Success;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.showSpinner = false;
    this.recordState();

    this.openSignalLoginInfo();
  }

  private failRedemption(error: string): void {
    this.state.showSpinner = false;
    this.state.purchaseFlowOutcome = OneTimePurchaseOutcome.Failure;
    this.state.purchaseResult = SignalLoginPurchaseResult.Failed;
    this.state.purchaseError = error;
    this.state.purchasePreparation = OneTimePurchasePreparation.Ready;
    this.state.dialogs.purchaseFailed = true;
    this.state.isPurchaseOptionEnabled = true;
    this.state.isActionEnabled = true;
    // The purchase stays owned and its context stays persisted, so retrying
    // reuses it rather than charging again.
    this.state.hasUnredeemedPurchase = this.billing.hasOwnedUnredeemedPurchase();
    this.recordState();
  }

  /** Drops the paid purchase context once it has been consumed. */
  private clearPurchaseContext(): void {
    this.state.inProgressRegistrationData.signalLoginPurchase = null;
    this.state.persistedSignalLoginPurchase = null;
    const owned: BillingPurchase | null = this.billing.ownedPurchase;
    if (owned !== null) {
      owned.state = BillingPurchaseState.Consumed;
      this.billing.ownedPurchase = owned;
    }
    this.effect('clearPersistedSignalLoginPurchase', {} as Record<string, Object>);
  }

  /* --------------------------------------------------------- navigation */

  private pushRoute(route: string): void {
    this.state.backStack = [this.state.route];
    this.state.route = route;
    this.effect('navigate', { 'route': route } as Record<string, Object>);
    this.recordState();
  }

  /**
   * Opens the login information screen.
   *
   * The pre-registration back stack is cleared here: once the account exists
   * there is nothing to go back to, and no phone verification or PIN step is
   * inserted anywhere, because a numberless account has neither.
   */
  private openSignalLoginInfo(): void {
    this.state.route = RegistrationRoute.SignalLoginInfo;
    this.state.backStack = [];
    this.state.showSpinner = false;
    this.effect('navigate', {
      'route': RegistrationRoute.SignalLoginInfo,
      'clearedBackStack': true,
      'insertedRoutes': []
    } as Record<string, Object>);
    this.recordState();
  }

  /**
   * Advances past credential preservation. Registration does not reach the
   * username step until the issued account identifier and recovery key have
   * been confirmed.
   */
  private completeCredentialPreservation(): void {
    this.state.savedCredentialConfirmed = true;
    this.state.route = RegistrationRoute.AddUsername;
    this.state.backStack = [];
    this.effect('navigate', {
      'route': RegistrationRoute.AddUsername,
      'clearedBackStack': true
    } as Record<string, Object>);
    this.recordState();
  }

  /* ---------------------------------------------- password manager pathway */

  /**
   * Offers the issued login to the platform password manager. This is the work
   * the navigation collector does while leaving the login screen, and the
   * outcome is routed straight back to the screen that owns the state.
   */
  saveCredentialForReadback(): void {
    if (this.credentialManager.isAvailable() === false) {
      this.state.dialogs.saveFailed = true;
      this.state.showSpinner = false;
      this.state.showConfirmSavedSheet = false;
      this.effect('saveCredentialToPasswordManager', { 'available': false } as Record<string, Object>);
      this.recordState();
      return;
    }
    const accountId: string = this.state.flow.aci;
    const recoveryKey: string = this.state.flow.accountEntropyPool;
    this.effect('saveCredentialToPasswordManager', {
      'username': normalizeAccountId(accountId),
      'password': recoveryKey,
      'routedTo': 'SignalLoginInfoViewModel'
    } as Record<string, Object>);
    this.credentialManager.saveCredential(accountId, recoveryKey);
    this.state.showSpinner = true;
    this.state.isReadbackRequested = true;
    this.state.showConfirmSavedSheet = true;
    this.state.savedCredentialConfirmed = false;
    this.state.dialogs.saveFailed = false;
    this.state.dialogs.saveNotConfirmed = false;
    this.recordState();
  }

  /**
   * The read-back of the saved credential came back. A save is not trusted on
   * its own: the credential is filtered by this account, its username is
   * normalized to an account identifier and its password parsed as a recovery
   * key, and only an exact two part match counts as safely stored.
   */
  completePasswordManagerReadback(): void {
    const accountId: string = this.state.flow.aci;
    this.state.showSpinner = true;
    this.effect('getCredentialFromPasswordManager', {
      'accountId': normalizeAccountId(accountId)
    } as Record<string, Object>);

    const readBack: UsernamePasswordCredential | null = this.credentialManager.getCredential(accountId);
    if (readBack === null) {
      this.failReadback();
      return;
    }
    const matched: boolean = credentialMatches(accountId, this.state.flow.accountEntropyPool, readBack.username, readBack.password);
    this.effect('compareReadBackCredential', {
      'type': readBack.type,
      'accountIdMatches': normalizeAccountId(readBack.username) === normalizeAccountId(accountId),
      'recoveryKeyMatches': matched,
      'confirmed': matched
    } as Record<string, Object>);
    if (matched === false) {
      this.failReadback();
      return;
    }
    this.state.dialogs.saveNotConfirmed = false;
    this.state.dialogs.saveFailed = false;
    this.state.showConfirmSavedSheet = false;
    this.state.showSpinner = false;
    this.recordState();
    this.completeCredentialPreservation();
  }

  /**
   * The saved credential could not be confirmed. The user stays on the login
   * screen and can either save again or record the credential by hand.
   */
  private failReadback(): void {
    this.state.showSpinner = false;
    this.state.showConfirmSavedSheet = false;
    this.state.savedCredentialConfirmed = false;
    this.state.dialogs.saveNotConfirmed = true;
    this.state.route = RegistrationRoute.SignalLoginInfo;
    this.recordState();
  }

  /* ------------------------------------------------------- manual recording */

  /** Opens the manual preservation path. */
  startManualCredentialEntry(): void {
    this.state.route = RegistrationRoute.SignalLoginManualSaveConfirmation;
    this.state.mode = SignalLoginCredentialEntryMode.Enter;
    this.state.enteredAccountId = '';
    this.state.enteredRecoveryKey = '';
    this.state.areCredentialsIncorrect = false;
    this.state.accountIdFieldIncorrect = false;
    this.state.recoveryKeyFieldIncorrect = false;
    this.state.isNextEnabled = false;
    this.effect('navigate', { 'route': RegistrationRoute.SignalLoginManualSaveConfirmation } as Record<string, Object>);
    this.recordState();
  }

  /**
   * Records an edit to one of the two credential halves. Editing either half
   * clears the incorrect flag, so a mistyped credential stays editable and a
   * corrected retry is reachable without recreating the account.
   */
  updateManualCredentialField(field: string, value: string): void {
    if (field === 'accountId') {
      this.state.enteredAccountId = value;
      this.state.accountIdFieldIncorrect = false;
    } else {
      this.state.enteredRecoveryKey = value;
      this.state.recoveryKeyFieldIncorrect = false;
    }
    this.state.areCredentialsIncorrect = false;
    this.state.isNextEnabled = value.length > 0;
    this.recordState();
  }

  /**
   * Confirms a manually recorded login. Both halves are compared with the
   * account material the registration flow already holds; a mismatch flags both
   * fields, because either half may have been copied wrongly.
   */
  submitManualSaveConfirmation(): void {
    this.effect('compareEnteredCredential', {
      'comparedAgainst': 'RegistrationFlowState',
      'comparedAccountId': true,
      'comparedRecoveryKey': true
    } as Record<string, Object>);
    const matched: boolean = credentialMatches(
      this.state.flow.aci,
      this.state.flow.accountEntropyPool,
      this.state.enteredAccountId,
      this.state.enteredRecoveryKey
    );
    if (matched === false) {
      this.state.areCredentialsIncorrect = true;
      this.state.accountIdFieldIncorrect = true;
      this.state.recoveryKeyFieldIncorrect = true;
      this.state.isNextEnabled = true;
      this.state.savedCredentialConfirmed = false;
      this.effect('manualSaveConfirmationRejected', {
        'staysOnRoute': RegistrationRoute.SignalLoginManualSaveConfirmation
      } as Record<string, Object>);
      this.recordState();
      return;
    }
    this.state.areCredentialsIncorrect = false;
    this.state.accountIdFieldIncorrect = false;
    this.state.recoveryKeyFieldIncorrect = false;
    this.state.isNextEnabled = true;
    this.state.savedCredentialConfirmed = true;
    this.state.mode = SignalLoginCredentialEntryMode.ConfirmSaved;
    this.effect('emitRegistrationFlowEvent.AccountCredentialRecorded', {} as Record<string, Object>);
    this.recordState();
    this.completeCredentialPreservation();
  }

  /* --------------------------------------------------------------- username */

  /** The username draft changed. */
  changeUsername(value: string): void {
    this.cancelReservationSettle();
    this.state.username = value;
    this.state.reservation = null;
    this.state.validationError = null;
    this.state.isSubmittable = false;
    if (value.length === 0) {
      this.state.isReserving = false;
      this.recordState();
      return;
    }
    if (this.state.discriminator.length > 0 && this.state.discriminatorFieldFocused === false) {
      this.requestUserChosenReservation();
      return;
    }
    this.recordState();
  }

  /** The discriminator field gained focus. */
  focusDiscriminator(): void {
    this.cancelReservationSettle();
    this.state.discriminatorFieldFocused = true;
    this.state.isReserving = false;
    this.recordState();
  }

  /**
   * The discriminator changed. Typing a discriminator reserves the exact
   * pairing the user asked for once they stop; clearing it drops that pairing,
   * because a reservation for digits the screen no longer holds can never be
   * confirmed.
   */
  changeDiscriminator(value: string): void {
    if (value.length === 0) {
      this.clearUserChosenDiscriminator();
      return;
    }
    this.cancelReservationSettle();
    this.state.discriminator = value;
    this.state.isDiscriminatorUserSet = true;
    this.state.validationError = null;
    this.state.isSubmittable = false;
    this.state.isReserving = true;
    this.recordState();
    this.scheduleReservationSettle();
  }

  /**
   * Clears a user chosen discriminator. The exact reservation made for the
   * erased pairing is invalidated immediately and cannot be confirmed, and no
   * fresh reservation is asked for until the field loses focus.
   */
  clearUserChosenDiscriminator(): void {
    this.cancelReservationSettle();
    this.state.discriminator = '';
    this.state.isDiscriminatorUserSet = false;
    this.state.reservation = null;
    this.state.validationError = null;
    this.state.isReserving = false;
    this.state.isSubmittable = false;
    this.recordState();
  }

  /** The discriminator field lost focus, so reservations may start again. */
  loseDiscriminatorFocus(): void {
    this.state.discriminatorFieldFocused = false;
    this.cancelReservationSettle();
    if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0 && this.state.reservation !== null) {
      this.state.isSubmittable = this.state.username.length > 0;
      this.recordState();
      return;
    }
    this.requestServiceAssignedReservation();
  }

  private scheduleReservationSettle(): void {
    this.settleHandle = setTimeout(() => {
      this.settleHandle = 0;
      this.settleReservation();
    }, RESERVATION_SETTLE_MILLISECONDS);
  }

  private cancelReservationSettle(): void {
    if (this.settleHandle !== 0) {
      clearTimeout(this.settleHandle);
      this.settleHandle = 0;
    }
  }

  /**
   * Runs after the user stopped typing. A reservation is never requested while
   * the field still has focus, because the response would race an edit that has
   * not reached the flow yet.
   */
  private settleReservation(): void {
    if (this.state.discriminatorFieldFocused) {
      this.state.isReserving = false;
      return;
    }
    if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0) {
      this.requestUserChosenReservation();
      return;
    }
    this.requestServiceAssignedReservation();
  }

  private requestUserChosenReservation(): void {
    const username: string = this.state.username;
    if (username.length === 0) {
      this.state.isReserving = false;
      this.state.isSubmittable = false;
      this.recordState();
      return;
    }
    const reservation: string = username + '.' + this.state.discriminator;
    const validationError: string = this.service.serviceUsernameValidationError;
    this.effect('reserveUsername.' + username + '.userChosen', {
      'reservation': reservation,
      'validationError': validationError
    } as Record<string, Object>);
    this.applyReservation(reservation, validationError);
  }

  private requestServiceAssignedReservation(): void {
    const username: string = this.state.username;
    if (username.length === 0) {
      this.state.isReserving = false;
      this.state.isSubmittable = false;
      this.recordState();
      return;
    }
    const assigned: string = this.service.serviceAssignedReservation.length > 0 ? this.service.serviceAssignedReservation : username;
    const validationError: string = this.service.serviceUsernameValidationError;
    this.effect('reserveUsername.' + username + '.serviceAssigned', {
      'reservation': assigned,
      'validationError': validationError
    } as Record<string, Object>);
    this.applyReservation(assigned, validationError);
  }

  /** A reservation failure stays retryable and never discards the current draft. */
  private applyReservation(reservation: string, validationError: string): void {
    this.state.isReserving = false;
    this.state.isDiscriminatorUserSet = this.state.discriminator.length > 0;
    if (validationError.length > 0) {
      this.state.reservation = null;
      this.state.validationError = validationError;
      this.state.isSubmittable = false;
      this.recordState();
      return;
    }
    this.state.reservation = reservation;
    this.state.validationError = null;
    this.state.isSubmittable = this.state.username.length > 0;
    this.recordState();
  }

  /** The reservation failed and the user asked to try again. */
  retryUsernameReservation(): void {
    if (this.state.username.length === 0) {
      return;
    }
    if (this.state.isDiscriminatorUserSet && this.state.discriminator.length > 0) {
      this.requestUserChosenReservation();
      return;
    }
    this.requestServiceAssignedReservation();
  }

  /**
   * The user asked to continue without a username. This is only a request: the
   * flow stays on the username screen and registration stays incomplete until
   * the request is confirmed.
   */
  requestUsernameSkip(): void {
    this.state.dialogs.confirmSkip = true;
    this.state.registrationComplete = false;
    this.state.finalRegistrationCommitted = false;
    this.recordState();
  }

  /** The skip confirmation was dismissed, so the username draft is still editable. */
  dismissUsernameSkipConfirmation(): void {
    this.state.dialogs.confirmSkip = false;
    this.state.registrationComplete = false;
    this.state.finalRegistrationCommitted = false;
    this.recordState();
  }

  /** The skip confirmation was accepted, which is the only way to skip. */
  confirmUsernameSkip(): void {
    if (this.state.dialogs.confirmSkip === false) {
      return;
    }
    this.effect('emitRegistrationFlowEvent.RegistrationComplete', {
      'username': '',
      'skippedUsername': true
    } as Record<string, Object>);
    this.state.dialogs.confirmSkip = false;
    this.state.registrationComplete = true;
    this.state.finalRegistrationCommitted = true;
    this.state.isSubmittable = false;
    this.state.route = RegistrationRoute.FullyComplete;
    this.state.flow.username = null;
    this.effect('navigate', { 'route': RegistrationRoute.FullyComplete } as Record<string, Object>);
    this.recordState();
  }

  /** The reserved username was confirmed and registration completes. */
  confirmUsername(): void {
    if (this.state.isSubmittable === false || this.state.reservation === null) {
      return;
    }
    this.effect('emitRegistrationFlowEvent.RegistrationComplete', {
      'username': this.state.username,
      'reservation': this.state.reservation as string
    } as Record<string, Object>);
    this.state.dialogs.confirmSkip = false;
    this.state.registrationComplete = true;
    this.state.finalRegistrationCommitted = true;
    this.state.route = RegistrationRoute.FullyComplete;
    this.state.flow.username = this.state.username;
    this.effect('navigate', { 'route': RegistrationRoute.FullyComplete } as Record<string, Object>);
    this.recordState();
  }

  /* ------------------------------------------------------------ accessors */

  currentState(): Record<string, Object> {
    return this.snapshot();
  }

  registrationSnapshot(): Record<string, Object> {
    return this.registrationData;
  }

  /** Records the purchase the app paid for so it survives a process recreation. */
  rememberPaidPurchase(context: SignalLoginPurchaseContext): void {
    this.state.inProgressRegistrationData.signalLoginPurchase = context;
    this.state.persistedSignalLoginPurchase = context;
    this.state.hasUnredeemedPurchase = true;
    const productId: string = this.service.loginConfiguration.playProductId;
    this.billing.ownedPurchase = new BillingPurchase(context.purchaseToken, BillingPurchaseState.Purchased);
    this.billing.product = new BillingProductOption(productId, context.purchaseOptionId, context.formattedPrice);
  }

  /** Restores a paid purchase context that was read back out of durable storage. */
  restorePaidPurchase(context: SignalLoginPurchaseContext): void {
    this.state.inProgressRegistrationData.signalLoginPurchase = context;
    this.state.persistedSignalLoginPurchase = context;
    this.state.hasUnredeemedPurchase = true;
    this.billing.ownedPurchase = new BillingPurchase(context.purchaseToken, BillingPurchaseState.Purchased);
  }
}

function asOptionalIdentity(value: Object | undefined): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  const text: string = asText(value);
  return text.length === 0 ? null : text;
}

/** Configuration the service exposes for the username screens. */
export class SignalServiceSnapshotExtension {
  serviceUsernameValidationError: string = '';
