  reset(): void {
    this.effects = [];
    this.orderedStates = [];
    this.effectCounts.clear();
  }

  effectCursor(): number {
    return this.effects.length;
  }

  effectsAfter(cursor: number): Record<string, Object>[] {
    return this.effects.slice(cursor);
  }

  addEffect(json: string): void {
    this.effects.push(jsonRecord(json));
  }

  /** Records one effect, numbering it with how many times it has happened. */
  recordEffect(json: string): void {
    const effect: Record<string, Object> = jsonRecord(json);
    const name: string = asText(effect['name']);
