    this.leaf.persistedPurchaseBlob = raw;
    return jsonRecord(raw);
  }

  /** Drops the durable blob once the purchase it described has been consumed. */
  async clearPersistedPurchase(context: common.UIAbilityContext): Promise<void> {
    const store = await preferences.getPreferences(context, PURCHASE_PREFERENCES_NAME);
