    this.store.initializeSignalLoginPayment();
  }

  continuePurchase(): void {
    this.store.continuePurchase();
  }

  completeCancelledPurchase(): void {
    this.store.completeCancelledPurchase();
  }

  foregroundPaymentScreen(): void {
    this.store.foregroundPaymentScreen();
  }

  completeSuccessfulPurchase(): void {
    this.store.completeSuccessfulPurchase();
  }

  completeFailedPurchase(): void {
    this.store.completeFailedPurchase();
