    this.store.submitManualSaveConfirmation();
  }

  requestUsernameSkip(): void {
    this.store.requestUsernameSkip();
  }

  dismissUsernameSkipConfirmation(): void {
    this.store.dismissUsernameSkipConfirmation();
  }

  confirmUsernameSkip(): void {
    this.store.confirmUsernameSkip();
  }

  clearUserChosenDiscriminator(): void {
    this.store.clearUserChosenDiscriminator();
  }

  loseDiscriminatorFocus(): void {
    this.store.loseDiscriminatorFocus();
  }

  changeUsername(value: string): void {
    this.store.changeUsername(value);
  }

  changeDiscriminator(value: string): void {
    this.store.changeDiscriminator(value);
  }

  async persistPurchaseContext(context: common.UIAbilityContext, value: Record<string, Object>): Promise<void> {
    await this.store.persistPurchaseContext(context, value);
  }

  async retryOwnedPurchaseAfterProcessReopen(context: common.UIAbilityContext): Promise<void> {
    this.repository = new RegistrationRepository(this.leaf);
    this.store = new RegistrationStore(this.repository, this);
    this.store.reopenRegistrationData();
    await this.store.retryOwnedPurchaseAfterReopen(context);
  }

