    this.store.startManualCredentialEntry();
  }

  updateManualCredentialField(field: string, value: string): void {
    this.store.updateManualCredentialField(field, value);
  }

  startPhoneNumberRegistration(): void {
    this.store.startPhoneNumberRegistration();
  }

  startRegistrationWithoutNumber(): void {
    this.store.startRegistrationWithoutNumber();
  }

  reloadSignalLoginPaymentPrice(): void {
    this.store.reloadSignalLoginPaymentPrice();
  }

  completePasswordManagerReadback(): void {
    this.store.completePasswordManagerReadback();
  }

  saveCredentialForReadback(): void {
    this.store.saveCredentialForReadback();
  }

  state(): Record<string, Object> {
    return this.store.state();
  }
}

