import { common } from '@kit.AbilityKit';
import { RegistrationPageOwner } from '../feature/RegistrationStore';

@Entry
@Component
struct Index {
  private readonly owner: RegistrationPageOwner = new RegistrationPageOwner();
  private abilityContext: common.UIAbilityContext | null = null;
  @State private revision: number = 0;
  @State private route: string = '';
  @State private formattedPrice: string = '';
  @State private priceType: string = '';
  @State private accountId: string = '';
  @State private recoveryKey: string = '';
  @State private enteredAccountId: string = '';
  @State private enteredRecoveryKey: string = '';
  @State private showSpinner: boolean = false;
  @State private showConfirmSkip: boolean = false;
  @State private saveNotConfirmed: boolean = false;
  @State private paymentUnavailable: boolean = false;
  @State private purchaseFailed: boolean = false;
  @State private credentialsIncorrect: boolean = false;
  @State private registrationComplete: boolean = false;
  @State private username: string = '';
  @State private reservation: string = '';
  @State private usernameError: string = '';

  aboutToAppear(): void {
    this.abilityContext = getContext(this) as common.UIAbilityContext;
    this.owner.appear();
    this.refresh();
  }

  private text(state: Record<string, Object>, key: string): string {
    const value: Object | undefined = state[key];
    return value === undefined || value === null ? '' : JSON.stringify(value);
  }

  private nested(state: Record<string, Object>, parent: string, key: string): string {
    const value: Object | undefined = state[parent];
    if (value === undefined || value === null) {
      return '';
    }
    const child: Record<string, Object> = JSON.parse(JSON.stringify(value)) as Record<string, Object>;
    const member: Object | undefined = child[key];
    return member === undefined || member === null ? '' : JSON.stringify(member);
  }

  private flag(state: Record<string, Object>, key: string): boolean {
    return this.text(state, key) === 'true';
  }

  private refresh(): void {
    const state: Record<string, Object> = this.owner.state();
    this.route = this.text(state, 'route');
    this.priceType = this.nested(state, 'price', 'type');
    this.formattedPrice = this.nested(state, 'price', 'formattedPrice');
    this.accountId = this.nested(state, 'flow', 'aci');
    this.recoveryKey = this.nested(state, 'flow', 'accountEntropyPool');
    this.enteredAccountId = this.text(state, 'enteredAccountId');
    this.enteredRecoveryKey = this.text(state, 'enteredRecoveryKey');
    this.showSpinner = this.flag(state, 'showSpinner');
    this.showConfirmSkip = this.flag(state, 'dialogs.confirmSkip');
    this.saveNotConfirmed = this.nested(state, 'dialogs', 'saveNotConfirmed') === 'true';
    this.paymentUnavailable = this.nested(state, 'dialogs', 'paymentUnavailable') === 'true';
    this.purchaseFailed = this.nested(state, 'dialogs', 'purchaseFailed') === 'true';
    this.credentialsIncorrect = this.flag(state, 'areCredentialsIncorrect');
    this.registrationComplete = this.flag(state, 'registrationComplete');
    this.username = this.text(state, 'username');
    this.reservation = this.text(state, 'reservation');
    this.usernameError = this.text(state, 'validationError');
    this.revision += 1;
  }

  private run(action: () => void): void {
    action();
    this.refresh();
  }

  build() {
    Column({ space: 12 }) {
      Text('Signal registration').fontSize(24).fontWeight(FontWeight.Bold)
      Text('Register without sharing a phone number')
      Text(`Route: ${this.route}`).id('route').fontSize(12)

      Text(`Price: ${this.formattedPrice} (${this.priceType})`).id('price')

      if (this.showSpinner) {
        LoadingProgress().id('payment-spinner').width(24).height(24)
      }

      if (this.paymentUnavailable) {
        Text('Payment is unavailable on this device. You can still register with a phone number.')
          .id('payment-unavailable')
      }

      if (this.purchaseFailed) {
        Text('The purchase could not be completed. Your paid purchase is kept; try again without paying again.')
          .id('purchase-failed')
      }

      if (this.saveNotConfirmed) {
        Text('The saved login could not be confirmed. Save it again or record it by hand.')
          .id('save-not-confirmed')
      }

      Column({ space: 8 }) {
        Text('Register with a phone number').id('choose-phone')
        Button('Phone number').id('start-phone').onClick(() => { this.run(() => { this.owner.startPhoneNumberRegistration(); }); })
        Button('Register without a number').id('start-numberless')
          .onClick(() => { this.run(() => { this.owner.startRegistrationWithoutNumber(); }); })
      }.width('100%')

      Column({ space: 8 }) {
        Button('Check purchase').id('payment-init').onClick(() => { this.run(() => { this.owner.initializeSignalLoginPayment(); }); })
        Button('Reload price').id('payment-reload').onClick(() => { this.run(() => { this.owner.reloadSignalLoginPaymentPrice(); }); })
        Button('Continue').id('payment-continue').onClick(() => { this.run(() => { this.owner.continuePurchase(); }); })
        Button('Purchase cancelled').id('payment-cancel').onClick(() => { this.run(() => { this.owner.completeCancelledPurchase(); }); })
        Button('Purchase failed').id('payment-failed').onClick(() => { this.run(() => { this.owner.completeFailedPurchase(); }); })
        Button('Purchase succeeded').id('payment-success').onClick(() => { this.run(() => { this.owner.completeSuccessfulPurchase(); }); })
        Button('Back to foreground').id('payment-foreground').onClick(() => { this.run(() => { this.owner.foregroundPaymentScreen(); }); })
      }.width('100%')

      Column({ space: 8 }) {
        Text(`Account identifier: ${this.accountId}`).id('login-aci')
        Text(`Recovery key: ${this.recoveryKey}`).id('login-recovery-key')
        Button('Save login to password manager').id('credential-save')
          .onClick(() => { this.run(() => { this.owner.saveCredentialForReadback(); }); })
        Button('Verify saved login').id('credential-readback').onClick(() => { this.run(() => { this.owner.completePasswordManagerReadback(); }); })
        Button('Record login by hand').id('credential-manual').onClick(() => { this.run(() => { this.owner.startManualCredentialEntry(); }); })
      }.width('100%')

      Column({ space: 8 }) {
        TextInput({ placeholder: 'Account identifier', text: this.enteredAccountId }).id('manual-account-id')
          .onChange((value: string) => {
            this.owner.updateManualCredentialField('accountId', value);
            this.enteredAccountId = value;
            this.refresh();
          })
        TextInput({ placeholder: 'Recovery key', text: this.enteredRecoveryKey }).id('manual-recovery-key')
          .onChange((value: string) => {
            this.owner.updateManualCredentialField('recoveryKey', value);
            this.enteredRecoveryKey = value;
            this.refresh();
          })
        if (this.credentialsIncorrect) {
          Text('Those values do not match the login you were given. Check both and try again.').id('manual-incorrect')
        }
        Button('Confirm recorded login').id('manual-confirm')
          .onClick(() => { this.run(() => { this.owner.submitManualSaveConfirmation(); }); })
      }.width('100%')

      Column({ space: 8 }) {
        TextInput({ placeholder: 'Username', text: this.username }).id('username-input')
          .onChange((value: string) => {
            this.owner.changeUsername(value);
            this.username = value;
            this.refresh();
          })
        Text(`Reservation: ${this.reservation}`).id('username-reservation')
        if (this.usernameError.length > 0) {
          Text(this.usernameError).id('username-error')
        }
        Button('Retry reservation').id('username-retry').onClick(() => { this.run(() => { this.owner.retryUsernameReservation(); }); })
        Button('Clear discriminator').id('discriminator-clear')
          .onClick(() => { this.run(() => { this.owner.clearUserChosenDiscriminator(); }); })
        Button('Commit username').id('username-confirm').onClick(() => { this.run(() => { this.owner.confirmUsername(); }); })
        Button('Skip username').id('username-skip').onClick(() => { this.run(() => { this.owner.requestUsernameSkip(); }); })
        if (this.showConfirmSkip) {
          Text('Skip choosing a username?').id('skip-confirm-text')
          Button('Keep username').id('skip-dismiss').onClick(() => { this.run(() => { this.owner.dismissUsernameSkipConfirmation(); }); })
          Button('Skip anyway').id('skip-confirm').onClick(() => { this.run(() => { this.owner.confirmUsernameSkip(); }); })
        }
      }.width('100%')

      if (this.registrationComplete) {
        Text('Registration complete').id('registration-complete')
      }
    }.width('100%').height('100%').padding(24).alignItems(HorizontalAlign.Start)
  }
}

