async retryOwnedPurchaseAfterReopen(context: common.UIAbilityContext): Promise<void> {
    const restored: SignalLoginPurchaseContext | null = await this.readDurablePurchaseContext(context);
    if (restored !== null) {
      this.flow.restorePaidPurchase(restored);
    } else {
      // Durable storage does not know about this purchase yet. The restored
      // registration data does, so it is adopted and written back before it is
      // redeemed: the receipt credential request context must be durable for any
      // later recovery, not only for this run.
      const inMemory: Record<string, Object> = asRecord(this.flow.registrationSnapshot()['persistedSignalLoginPurchase']);
      if (isEmptyRecord(inMemory) === false) {
        const adopted: SignalLoginPurchaseContext = SignalLoginPurchaseContext.fromJson(inMemory);
        this.flow.restorePaidPurchase(adopted);
        await this.writeDurablePurchaseContext(context, adopted);
      }
    }
    this.flow.reopenPaymentScreen();
    this.flow.resumeOwnedPurchase();
  }

  /**
   * Reads the purchase context out of durable storage. A store that cannot be
   * reached leaves the paid purchase recoverable rather than aborting the run.
   */
  private async readDurablePurchaseContext(context: common.UIAbilityContext): Promise<SignalLoginPurchaseContext | null> {
    try {
      const persisted: Record<string, Object> = await this.repository.readPersistedPurchase(context);
      const nested: Record<string, Object> = asRecord(persisted['signalLoginPurchase']);
      const source: Record<string, Object> = isEmptyRecord(nested) ? persisted : nested;
      const restored: SignalLoginPurchaseContext = SignalLoginPurchaseContext.fromJson(source);
      if (restored.purchaseToken.length > 0) {
        return restored;
      }
      return null;
    } catch (error) {
      this.effect('{"name":"readInProgressRegistrationData","backingIo":"unreachable","failed":true}');
      return null;
    }
  }

  private async writeDurablePurchaseContext(context: common.UIAbilityContext, value: SignalLoginPurchaseContext): Promise<void> {
    try {
      await this.repository.persistPurchase(context, value.toJson());
    } catch (error) {
      this.effect('{"name":"persistSignalLoginPurchase","failed":true}');
    }
  }

