  /**
   * Applies the result the store purchase sheet came back with. The sheet result
   * is the only thing that can move the payment screen on from "unresolved", so
   * the purchase flow is completed through here rather than from each screen.
   */
  completePurchaseFlow(result: string): void {
    if (result === OneTimePurchaseOutcome.UserCancelled) {
      this.flow.completeCancelledPurchase();
      return;
    }
    if (result === OneTimePurchaseOutcome.Success) {
      this.flow.completePurchase();
      return;
    }
    this.flow.completeFailedPurchase();
  }

